select importer.rezepte('[["3-stunden-brot","komponente","3 Stunden Brot",null,null,null,null,null,null,["Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Wasser",330.0,0,null],["Milch",100.0,0,null],["Malz",6.0,0,null],["Sauerteig",20.0,0,null],["Frischhefe",15.0,0,null],["Salz",15.0,0,null],["Halbweissmehl",480.0,0,null],["Roggenmehl",180.0,0,null]],[]]]],["4er-weizenlaib","komponente","4er Weizenlaib",null,"Brot",null,null,null,null,["2 von 11 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[["Kochstück",[["Weissmehl",60.0,0,null],["Wasser",180.0,0,null]],[]],["Vorteig",[["Halbweissmehl",100.0,0,null],["Wasser",100.0,0,null],["Sauerteig B",10.0,0,null]],[]],["Hauptteig",[["Kochstück",null,0,null],["Vorteig",null,0,null],["Ruchmehl",360.0,0,null],["Vollkornmehl",200.0,0,null],["Wasser",330.0,0,null],["Salz",14.0,0,null]],[]]]],["algin-lauge","komponente","Algin Lauge",null,null,null,null,null,null,["1 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Wasser",1000.0,2,"1 L (1 ml = 1 g)"],["Algin",5.0,0,null]],[["Mixen und entlüften",null,null,null,null,null,false]]]]],["aloo-gobi","gericht","Aloo Gobi",null,null,"Betty Bossy",4,null,null,["12 von 16 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Zwiebeln",null,0,"2 Zwiebeln"],["Knoblauchzehen",null,0,"3 Knoblauchzehen"],["Ingwer",30.0,0,null],["Tomaten",null,0,"2 Tomaten"],["Blumenkohl",600.0,0,null],["Kartoffeln Festkochend",300.0,0,null],["Ghee",null,0,"1 EL"],["Kreuzkümmel",null,0,"1 TL"],["Senfkörner",null,0,"1 TL"],["Rohzucker",null,0,"1 TL"],["Sesam",null,0,"2 TL"],["Korianderpulver",null,0,"1 TL"],["Kurkuma",null,0,"1 TL"],["Chilipulver",null,0,"0.5 TL"],["Salz",null,0,"0.75 TL"],["Wasser",150.0,0,null]],[["Zwiebeln und Knoblauch schälen, beides fein hacken. Ingwer schälen, fein reiben. Tomaten in Würfeli schneiden. Blumenkohl in Röschen schneiden. Kartoffeln schälen, in Schnitze schneiden.",null,null,null,null,null,false],["Ghee im Brattopf heiss werden lassen. Kreuzkümmel und Senfkörner ca. 2 Min. rösten. Zwiebeln, Knoblauch, Ingwer und Zucker ca. 5 Min. mitrösten. Tomaten beigeben, kurz rührbraten.",null,null,null,null,null,false],["Blumenkohl und Kartoffeln beigeben, ca. 5 Min. rührbraten. Sesam, Korianderpulver, Kurkuma, Chilipulver und Salz beigeben, ca. 2 Min. mitrührbraten. Wasser dazugiessen, zugedeckt ca. 20 Min. köcheln.",null,null,null,null,null,false]]]]],["aloo-gobi-2","gericht","Aloo Gobi",null,null,"Shiba",4,null,null,["1 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","17 von 19 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Ghee oder Kokosfett alternativ: neutrales Öl zum anbraten",null,0,"2 EL"],["Kreuzkümmel",null,0,"½ TL"],["Senfsamen optional",null,0,"½ TL"],["mittelgrosse Zwiebeln gewürfelt oder längliche Streifen",null,0,"2 mittelgrosse Zwiebeln gewürfelt oder längliche Streifen"],["Knoblauchzehen",null,0,"3 Knoblauchzehen"],["Ingwerstück",15.0,0,null],["mittelgrosse Tomaten",null,0,"3 mittelgrosse Tomaten"],["passierte Tomaten (optional: Falls du nicht genug oder keine frischen Tomaten da hast)",200.0,2,"200 ml (1 ml = 1 g)"],["mittelgrosse Kartoffeln",null,0,"3 mittelgrosse Kartoffeln"],["mittelgrosser Blumekohl",null,0,"1 mittelgrosser Blumekohl"],["Salz & Pfeffer nach Geschmack",null,0,null]],[]],["Gewürze",[["Korianderpulver",null,0,"1,5 TL"],["Garam Masala",null,0,"1 TL"],["Paprikapulver",null,0,"1 TL"],["Chilipulver",null,0,"1 TL"],["Kurkuma",null,0,"½ TL"],["Salz & Pfeffer nach Geschmack",null,0,null]],[]],["Sonstiges zum servieren",[["frischer Koriander",null,0,null],["frische Chilischote",null,0,null]],[]],["Zubereitung",[],[["Die Kartoffeln schälen, in grobe Stücke schneiden (siehe oben) und in eine grosse Schüssel mit Wasser einweichen. Das sorgt dafür dass die Kartoffeln etwas an Stärke verlieren und beim kochen nicht so sehr kleben.",null,null,null,null,null,false],["Den Blumenkohl putzen, waschen und in Röschen teilen.",null,null,null,null,null,false],["Die Zwiebeln schälen und nach belieben schneiden. Knoblauch, Ingwer schälen und in einem Mörser zu einer Paste stampfen. (optional fein hacken). Die Tomaten waschen und in grobe Stücke schneiden.",null,null,null,null,null,false],["Das Ghee in in einer Pfanne erhitzen. Kreuzkümmel und Senfsamen darin kurz anbraten. (ca. 30 Skeunden)",null,null,null,null,null,false],["Die Zwiebeln dazugeben und auf mittlere Hitze anschwitzen. (Ca. 1 Minute)",null,null,null,null,null,false],["Die Gewürze und die Knoblauch-Ingwerpaste hinzufügen und kurz mit anbraten bzw. schmoren.",null,null,null,null,null,false],["Mit den Tomaten, passierte Tomaten ablöschen.",null,null,null,null,null,false],["Nach Geschmack salzen und alles einmal scharf anbraten.",null,null,null,null,null,false],["Kartoffel und Blumenkohlröschen dazugebe und alles scharf anbraten. Chili dazugeben.",null,null,null,null,null,false],["Etwas Wasser dazugeben (ca. 100 ml). Mit geschlossenem Deckel 20-30 Minuten auf mittlere-niedrige Hitze köcheln lassen, bis Kartoffeln un der Blumenkohl gar sind.",null,null,null,null,null,false],["Mit frischem Koriander und Chili servieren und geniessen.",null,null,null,null,null,false],["SHIBAS NOTIZEN",null,null,null,null,null,false],["Die Garzeit vom Blumenkohl kann abweichen, je nachdem wie gross/klein man den Blumenkohl schneidet.",null,null,null,null,null,false],["Falls du keine frische Tomaten da hast, kannst du es durch mehr passierte Tomaten ersetzten oder halb halb machen.",null,null,null,null,null,false],["Als Beilage empfehle ich Basmatireis oder Roti dazu.",null,null,null,null,null,false],["Die Garzeit von Kartoffeln und Gemüse hängt davon ab wie gross/klein ihr es schneidet. Ich habe Kartoffeln eher grob gehalten und den Blumenkohl kleiner geschnitten.",null,null,null,null,null,false],["Traditionell wird am Schluss noch pro Portion mit einem Klecks Butter über das noch heisse Aloo Gobi serviert.",null,null,null,null,null,false]]]]],["aloo-gobi-3","gericht","Aloo Gobi",null,null,null,4,null,null,["11 von 13 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["kleiner Blumenkohl",null,0,"1 kleiner Blumenkohl"],["Kartoffel",null,0,"1 Kartoffel"],["Tomaten",null,0,"2 Tomaten"],["gehackte Zwiebeln",null,0,"2 gehackte Zwiebeln"],["Wenig Ingwer",null,0,null],["Kreuzkümmel",null,0,"1/2 TL"],["Kurkuma",null,0,"1 TL"],["Chili Pulver",null,0,"1/2 TL"],["Salz",null,0,null],["Joghurt",150.0,0,null],["Zucker",null,0,"1 TL"],["Koriander gehackt",null,0,null],["Wasser",250.0,0,null]],[["Zwiebel anbraten. Mit Kreuzkümmel bestäuben Kartoffeln, Blumenkohl, dazugeben. 3 min Weiterbraten.",null,null,null,null,null,false],["Gewürze und Tomaten dazugeben. 3 min Weiterbraten.",null,null,null,null,null,false],["Wasser und Salz zugeben, bei kleiner Hitze 20 Min köcheln.",null,null,null,null,null,false],["Mit Joghurt und Zucker abschmecken. Mit Koriander bestreuen.",null,null,null,null,null,false]]]]],["asia-dressing","komponente","Asia Dressing",null,null,null,null,null,null,["4 von 10 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Zwiebel",280.0,0,null],["Reisessig",80.0,0,null],["Sojasauce",160.0,0,null],["Wasser",120.0,0,null],["Zucker",null,0,"2 TL"],["Pr Salz",null,0,"4 Pr Salz"],["Pr Pfeffer",null,0,"4 Pr Pfeffer"],["Senf",null,0,"1 EL"],["Traubenkeröl",240.0,0,null],["Sesamöl",240.0,0,null]],[["Alles im Thermomix auf Stufe 10 für 20 Sekunden mixen",null,null,null,null,null,false]]]]],["asia-vinaigrette","komponente","Asia Vinaigrette",null,null,null,null,null,null,["5 von 11 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Knoblauch gehackt",20.0,0,null],["Ingwer gehackt",20.0,0,null],["Chili gehackt",null,0,"1 Chili gehackt"],["Mirin",75.0,0,null],["Yuzusaft",30.0,0,null],["Sojasauce",30.0,0,null],["Sake",5.0,0,null],["Zucker",null,0,"1 EL"],["Traubenkernöl",null,0,"2 EL"],["Wenig Sesamöl",null,0,null],["Schwarzer Pfeffer",null,0,null]],[]]]],["asia-vinaigrette-2","komponente","Asia Vinaigrette",null,null,null,null,null,null,["2 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","7 von 9 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Mirin Reiswein",75.0,2,"75 ml (1 ml = 1 g)"],["Ponzu-Sojasauce (mit Yuzu),",75.0,2,"75 ml (1 ml = 1 g)"],["Traubenkern- oder Rapsöl",null,0,"2 EL"],["einige Spritzer asiatisches Sesamöl",null,0,null],["Knoblauch, feingehackt",null,0,"2 EL"],["Ingwerwurzel, gerieben",null,0,"2 EL"],["roter, scharfer Chili, feingehackt",null,0,"1 roter, scharfer Chili, feingehackt"],["Zucker",null,0,"1 EL"],["schwarzer Pfeffer, frisch gemahlen",null,0,null]],[]]]],["asiatischer-rotkrautsalat","komponente","Asiatischer Rotkrautsalat",null,null,null,null,null,null,["10 von 10 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Kopf Rotkohl (500 g)",null,0,"½ Kopf Rotkohl (500 g)"],["Frühlingszwiebeln",null,0,"2 Frühlingszwiebeln"],["Knoblauchzehen",null,0,"2 Knoblauchzehen"],["Ingwer (15 g), in feine Streifen geschnitten",null,0,"2 TL"],["Sojasauce",null,0,"3 EL"],["Reisessig",null,0,"2 EL"],["Agavendicksaft",null,0,"1 EL"],["Mirin (japanischer Reiswein)",null,0,"1 EL"],["geröstetes Sesamöl, optional",null,0,"2 TL"],["Sesamsamen, geröstet",null,0,"3 EL"]],[]]]],["asiatisches-rindsgeschnetzeltes","gericht","Asiatisches Rindsgeschnetzeltes",null,null,null,10,null,null,["1 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","11 von 14 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Bundzwiebeln mit dem Grün",null,0,"7.5 Bundzwiebeln mit dem Grün"],["Pak-Choi",1000.0,0,null],["Knoblauchzehen",null,0,"5 Knoblauchzehen"],["Öl zum Braten",null,0,null],["geschnetzeltes Rindfleisch (à la minute)",1500.0,0,null],["Salz",null,0,"1.88 TL"],["wenig Pfeffer",null,0,null],["Maizena",null,0,"2.5 EL"],["grobkörniger Rohzucker",null,0,"2.5 EL"],["Limette",null,0,"2.5 Limette"],["Wasser",500.0,2,"5 dl (1 ml = 1 g)"],["Miso-Paste",null,0,"2.5 EL"],["Fischsauce oder Sojasauce",null,0,"2.5 EL"],["Koriander",null,0,"2.5 Bund"]],[["Bundzwiebeln in Ringe schneiden, Grün beiseite stellen. Pak-Choi in Streifen schneiden. Knoblauch schälen, in Scheibchen schneiden.",null,null,null,null,null,false],["Öl in einer Bratpfanne heiss werden lassen. Fleisch würzen, mit Maizena bestäuben, portionenweise je ca. 1 Min. braten. Herausnehmen, Fleisch beiseite stellen.",null,null,null,null,null,false],["Wenig Öl in derselben Pfanne warm werden lassen. Bundzwiebeln, Pak-Choi, Knoblauch und Zucker ca. 2 Min. andämpfen. Von der Limette den ganzen Saft dazupressen, Wasser dazugiessen, Miso-Paste und Fischsauce beigeben, aufkochen. Hitze reduzieren, ca. 3 Min. köcheln. Fleisch mit dem entstandenen Saft und dem Bundzwiebelgrün wieder beigeben, nur noch heiss werden lassen.",null,null,null,null,null,false],["Korianderblättchen abzupfen, darauf verteilen.",null,null,null,null,null,false]]]]],["aelplermagronen","gericht","Älplermagronen",null,null,null,6,null,null,["2 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","4 von 10 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Zwiebeln",null,0,"3 Zwiebeln"],["Knoblauchzehen",null,0,"3 Knoblauchzehen"],["fest kochende Kartoffeln",600.0,0,null],["Speckwürfeli",225.0,0,null],["Gemüsebouillon",750.0,2,"7.5 dl (1 ml = 1 g)"],["Halbrahm",300.0,2,"3 dl (1 ml = 1 g)"],["Teigwaren (z. B. Älplermagronen)",375.0,0,null],["geriebener Gruyère",90.0,0,null],["Salz",null,0,"0.75 TL"],["wenig Pfeffer",null,0,null]],[["Zwiebeln, Knoblauch und Kartoffeln schälen. Zwiebeln in Ringe, Knoblauch in Scheibchen und Kartoffeln in Würfel schneiden. Zwiebeln, Knoblauch und Speck in einer beschichteten Bratpfanne goldbraun braten, herausnehmen, beiseite stellen.",null,null,null,null,null,false],["Bouillon und Rahm in einer Pfanne aufkochen, Kartoffeln und Teigwaren beigeben, zugedeckt bei kleiner Hitze ca. 10 Min. kochen, bis die Teigwaren al dente sind und alle Flüssigkeit aufgesogen ist.",null,null,null,null,null,false],["Käse unter die Kartoffeln und Teigwaren mischen, würzen, auf Teller verteilen. Beiseite gestellte Speck-Mischung darauf anrichten.",null,null,null,null,null,false]]]]],["backteig","komponente","Backteig",null,null,null,null,null,null,["2 von 4 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Mehl",375.0,0,null],["Bier",300.0,0,null],["Salz",null,0,"1 tl"],["Backpulver",null,0,"3 tl"]],[]]]],["baguettes","gericht","Baguettes",null,"Brot",null,4,null,null,["2 von 13 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[["Weizensauerteig",[["Weizenmehl",20.0,0,null],["Wasser (25-30°C)",15.0,0,null],["Anstellgut",5.0,0,null]],[]],["Weizenpoolish",[["Weizenmehl",115.0,0,null],["Roggenmehl",5.0,0,null],["Wasser (10-15°C)",115.0,0,null],["Backhefe",0.3,0,null]],[]],["Hauptteig",[["reifer Sauerteig",null,0,null],["reifes Poolish",null,0,null],["Wasser (30°C)",380.0,0,null],["Weizenmehl",535.0,0,null],["Backhefe",1.0,0,null],["Salz",15.0,0,null]],[]],["Zubereitung",[],[["1.für den Weizensauerteig alle Zutaten in einer Schüssel verrühren, gut durchmischen und zugedeckt bei (24-26°C) für 12-16 Stunden reifen lassen.",null,null,null,null,null,false],["TIPP: Unter Autolyse wird die Teigrast vor dem eigentlichen Knetprozess verstanden. Während der Autolyse können alle Mehl- bestandteile gut aufquellen. Dadurch wird die Kleberentwicklung gefördert, der Knetprozess verkürtzt und die Kleberstuktur beim Kneten geschont.",null,null,null,null,null,false],["Aufarbeitung",null,null,null,null,null,false],["Die Teigwanne aus dem Kühlschrank geben und 45-60 Minuten bei Raumtemperatur akklimatisieren lassen. Den Teig vorsichtig auf eine mit wenig Weizenmehl bestaubte Arbeitsfläche stürzen und zu 4 gleich grossen Teiglingen abstechen. Nun die Teiglinge ganz vorsichtig zu runden Laiben formen ohne sie auf viel Spannung zu bringen. Nach 10-25 Minuten die Teiglinge von oben nach unten vorsichtig einfalten und leicht ausrollen. Die fertig geformten Teig- linge nun mit dem Schluss nach oben in gestaubte Baguettetücher legen und 30-50 Minuten entspannen lassen.",null,null,null,null,null,false],["Backen",null,null,null,null,null,false],["Die entspannten Teiglinge mit dem Schluss nach unten auf ein Backpapier legen und in den auf 230-240°C vorgeheizten Ofen ge- ben und mit viel Schwaden ca. 20 Minuten backen. Bei Baguettes ist eine gute Unterhitze sehr wichtig! Daher den Ofen mit einem Backstein oder einem Backblech vorheizen und die Teiglinge mit einem Backpapier direkt auf die heisse Oberfläche ziehen!",null,null,null,null,null,false]]]]],["bami-goreng","gericht","Bami Goreng",null,null,null,10,null,null,["1 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","5 von 10 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Chinesische Nudeln (z. B. Mei Yang Chinese Noodles)",320.0,0,null],["Salzwasser, siedend",null,0,null],["Rüebli",1000.0,0,null],["Bundzwiebeln mit dem Grün",null,0,"7.5 Bundzwiebeln mit dem Grün"],["Pak-Choi",750.0,0,null],["Erdnussöl zum Braten",null,0,null],["geschnetzeltes Pouletfleisch",1000.0,0,null],["Sojasauce oder Ketjap Manis",null,0,"7.5 EL"],["Sambal Oelek",null,0,"2.5 EL"],["Gemüsebouillon",250.0,2,"2.5 dl (1 ml = 1 g)"]],[["Nudeln im siedenden Salzwasser ca. 3 Min. al dente kochen, abtropfen, kalt abspülen.",null,null,null,null,null,false],["Rüebli schälen, in dünne, ca. 5 cm lange Streifen schneiden. Bundzwiebeln schräg in Ringe schneiden, Bundzwiebelgrün beiseite stellen. Pak-Choi in ca. 1 cm dicke Streifen schneiden.",null,null,null,null,null,false],["Öl im Wok oder in einer weiten beschichteten Bratpfanne heiss werden lassen. Poulet portionenweise je ca. 2 Min. braten, herausnehmen. Wenig Öl in derselben Pfanne heiss werden lassen. Nudeln ca. 3 Min. rührbraten, herausnehmen. Wenig Öl in derselben Pfanne heiss werden lassen. Rüebli ca. 3 Min. rührbraten, Bundzwiebeln und Pak-Choi ca. 2 Min. mitrührbraten. Ketjap Manis und Sambal Oelek beigeben, Bouillon dazugiessen, aufkochen. Hitze reduzieren, Poulet und Nudeln wieder beigeben, nur noch heiss werden lassen. Beiseite gestelltes Bundzwiebelgrün darüberstreuen.",null,null,null,null,null,false]]]]],["bauernbrot","komponente","Bauernbrot",null,null,null,null,null,null,["1 von 5 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Teig",null,0,null],["Weizenmehl (Typ 550)",550.0,0,null],["Wasser",350.0,0,null],["Hefe, frisch",5.0,0,null],["Salz",13.0,0,null]],[["Für den Teig Mehl, Wasser und Hefe während 12–15 Minuten zu einem glatten Teig kneten, 3 Minuten vor Ende Salz zugeben. 3 Stunden bei Raumtemperatur gehen lassen, währenddessen mehrere Male dehnen und falten.",null,null,null,null,null,false],["Zu sechs Laiben formen und gut bemehlt auf ein Blech mit Backpapier geben. Für 9–12 Stunden mit einem Tuch bedeckt im Kühlschrank ruhen lassen.",null,null,null,null,null,false],["Die Brote mit einer Rasierklinge in Kreuzform einschneiden und bei Zimmertemperatur eine weitere Stunde reifen lassen. Ofen auf 250 °C vorheizen.",null,null,null,null,null,false],["Die Brote in den Ofen schieben und den Backofenboden mit etwas Wasser befeuchten. 20 Minuten mit Dampf backen, dann die Temperatur auf 220 °C reduzieren und 20–30 Minuten bis zur gewünschten Bräune fertig backen.",null,null,null,null,null,false]]]]],["bechamel","komponente","Béchamel",null,null,null,null,null,null,["3 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Butter",480.0,0,null],["Mehl",480.0,0,null],["Milch",6000.0,2,"6 l (1 ml = 1 g)"],["Rahm",2000.0,2,"2 l (1 ml = 1 g)"],["Weisswein",300.0,2,"3 dl (1 ml = 1 g)"],["Salz",60.0,0,null],["Muskat",4.0,0,null]],[]]]],["bianco","komponente","Bianco",null,"Brot",null,null,null,null,["2 von 11 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[["Poolish",[["Weissmehl",400.0,0,null],["Wasser, handwarm",300.0,0,null],["Frischhefe",1.0,0,null]],[]],["Vorteig",[["Weissmehl",200.0,0,null],["Wasser, handwarm",200.0,0,null],["Sauerteig",25.0,0,null]],[]],["Hauptteig",[["Poolish",null,0,null],["Vorteig",null,0,null],["Salz",14.0,0,null],["Weissmehl",170.0,0,null],["Hefe",10.0,0,null]],[]],["Zubereitung",[],[["Poolish",null,null,null,null,null,false],["Alles in der Maschine 2-3 Minuten mischen. 1-3 Stunden bei Raumtemperatur gären lassen. Dann 16-48 Stunden im Kühlschrank ruhen lassen.",null,null,null,null,null,false],["Vorteig",null,null,null,null,null,false],["Alles gut mischen. Bei Raumtemperatur 8 - 12 Stunden gären lassen.",null,null,null,null,null,false],["Hauptteig",null,null,null,null,null,false],["Alles in der Maschine 10-12 Minuten kneten. Fenstertest. 60-90 Minuten bei Raumtemperatur zugedeckt gären lassen.",null,null,null,null,null,false],["Formen",null,null,null,null,null,false],["In Stücke von 660 g teilen und rund formen. In einem Gärkorb 30-50 Minuten gehen lassen.",null,null,null,null,null,false],["Backen",null,null,null,null,null,false],["Ofen auf 200 Grad vorheizen.",null,null,null,null,null,false],["Brote übers Kreuz einschneiden und für 30 Minuten mit beschwaden backen. Hitze auf 170 Grad reduzieren und 20 Minuten fertig backen.",null,null,null,null,null,false]]]]],["bircher-mueesli","komponente","Bircher Müesli",null,null,null,null,null,null,["Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Müesli",500.0,0,null],["Joghurt",2000.0,0,null],["Früchte Mix",500.0,0,null],["Agavendicksaft",200.0,0,null]],[]]]],["blumenkohl","komponente","Blumenkohl",null,null,null,null,null,null,["2 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","9 von 15 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["grosse Blumenkohl",null,0,"2 grosse Blumenkohl"],["Rapsöl, kaltgepresst",100.0,2,"100 ml (1 ml = 1 g)"],["Meersalz, fein",null,0,null],["Sesam-Yoghurt",null,0,null],["griechischer Joghurt",300.0,0,null],["Tahini (Sesampaste)",75.0,0,null],["Bio-Zitrone, Abrieb",null,0,"1 Bio-Zitrone, Abrieb"],["Dukkah (arabische Gewürzmischung aus Kräutern, Nüssen und Gewürzen)",null,0,"3 EL"],["Kräuter-Schalotten-Chili-Vinaigrette",null,0,null],["glatte Petersilie, fein gehackt",30.0,0,null],["frischer Koriander, fein gehackt",50.0,0,null],["Schalotte, fein gewürfelt",null,0,"1 Schalotte, fein gewürfelt"],["mittelscharfer Chili, fein gehackt (z.B. Peperoncino)",null,0,"1 mittelscharfer Chili, fein gehackt (z.B. Peperoncino)"],["Olivenöl ‚extra vergine’",100.0,2,"100 ml (1 ml = 1 g)"],["Bio-Limetten, Saft und Abrieb",null,0,"1-2 Bio-Limetten, Saft und Abrieb"]],[]]]],["brauner-kalbsfond","komponente","Brauner Kalbsfond",null,null,null,null,null,null,["1 von 11 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt. Angabe im Original: 5 Liter.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Erdnussöl",50.0,0,null],["Kalbsknochen",4000.0,0,null],["Kalbsfüsse",1000.0,0,null],["Mirepoix, bunt",800.0,0,null],["Tomatenpüree",120.0,0,null],["Weisswein",1000.0,0,null],["Wasser",7000.0,0,null],["Salz",40.0,0,null],["Gewürzsäcklein",null,0,"1 Gewürzsäcklein"],["Thymian, frisch",10.0,0,null],["Majoran, frisch",10.0,0,null]],[["Die Kalbsknochen möglichst klein hacken.",null,null,null,null,null,false],["Die Kalbsfüsse tiefgekühlt in kleine Stücke zersägen.",null,null,null,null,null,false],["Gewürzsäcklein aus Pfefferkörnern, Gewürznelken, Thymian,",null,null,null,null,null,false],["Lorbeer, Rosmarin, Thymian und Majoran bereitstellen.",null,null,null,null,null,false],["Bratgeschirr mit Erdnussöl ausgiessen und erhitzen.",null,null,null,null,null,false],["Kalbsknochen und Kalbsfüsse langsam braun rösten.",null,null,null,null,null,false],["Mirepoix beigeben und mitrösten.",null,null,null,null,null,false],["Fettstoff ableeren und entsorgen.",null,null,null,null,null,false],["Tomatenpüree beigeben und mitrösten.",null,null,null,null,null,false],["2–3 Mal mit wenig Wasser ablöschen und bis zur Glace einkochen. – Weisswein zugeben und vollständig einkochen lassen.",null,null,null,null,null,false],["Mit Wasser auffüllen und zum Siedepunkt bringen, Salz beigeben. – Öfters abschäumen und abfetten.",null,null,null,null,null,false],["3 Stunden am Siedepunkt sieden lassen.",null,null,null,null,null,false],["Während der letzten Stunde das Gewürzsäcklein beigeben.",null,null,null,null,null,false],["Abschmecken, durch ein Passiertuch passieren und nochmals",null,null,null,null,null,false],["abfetten.",null,null,null,null,null,false],["Zur weiteren Verwendung rasch abkühlen.",null,null,null,null,null,false]]]]],["brombeer-cheesecake","gericht","Brombeer-Cheesecake",null,null,null,8,null,null,["5 von 11 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Butter",70.0,0,null],["Shortbread (z.B. Walker)",250.0,0,null],["Zimt",null,0,"1 TL"],["Doppelrahm-Frischkäse (z.B. Philadelphia)",800.0,0,null],["Zucker",200.0,0,null],["Eier",null,0,"4 Eier"],["Bio-Zitrone",null,0,"1 Bio-Zitrone"],["Brombeeren",100.0,0,null],["Zucker",null,0,"2 EL"],["Wasser",null,0,"1 EL"],["Crème fraîche",300.0,0,null]],[["Ofen auf 180 Grad vorheizen.",null,null,null,null,null,false],["Butter in einer kleinen Pfanne schmelzen, etwas abkühlen. Guetzli im Cutter fein mahlen oder in einem Plastikbeutel mit dem Wall­holz fein zerstossen, mit dem Zimt und der Butter mischen. Masse auf dem Formenboden verteilen, gut andrücken, kühl stellen.",null,null,null,null,null,false],["Frischkäse, Zucker und Eier in einer Schüssel mit den Schwingbesen des Handrührgeräts verrühren. Von der Zitrone die Schale dazureiben, mischen. Masse auf dem Guetzliboden verteilen, Form auf ein Backblech stellen.",null,null,null,null,null,false],["Backen: ca. 40 Min. in der unteren Hälfte des Ofens. Cheesecake mit dem Blech herausnehmen, auf dem Blech ca. 15 Min. abkühlen.",null,null,null,null,null,false],["Brombeeren mit dem Zucker und dem Wasser aufkochen, ca. 5 Min. weich köcheln, durch ein Sieb streichen, etwas abkühlen. Crème fraîche auf dem lauwarmen Cheesecake verteilen, Püree löffelweise daraufgeben, mit einem Holzspiesschen marmorieren.",null,null,null,null,null,false],["Fertig backen: ca. 15 Min. Cheesecake mit dem Blech herausnehmen, auf dem Blech auskühlen, zugedeckt mind. 6 Std. kühl stellen. Formenring entfernen.",null,null,null,null,null,false]]]]],["buchweizenbrot","gericht","Buchweizenbrot",null,"Brot",null,6,null,null,["2 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","3 von 9 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Wasser",200.0,2,"2 dl (1 ml = 1 g)"],["Buchweizen",100.0,0,null],["Mehl",450.0,0,null],["Buchweizenmehl",50.0,0,null],["Salz",null,0,"2 TL"],["Trockenhefe",null,0,"0.25 TL"],["Wasser",310.0,2,"3.1 dl (1 ml = 1 g)"],["Sauerteig f",10.0,0,null],["Melasse oder 1 TL Honig",null,0,"1 EL"]],[["Wasser mit dem Buchweizen aufkochen, zugedeckt bei kleinster Hitze ca. 15 Min. quellen lassen. Buchweizen auskühlen.",null,null,null,null,null,false],["Mehle, Buchweizenmehl, Salz und Hefe in einer Schüssel mischen. Wasser, Sauerteig, Melasse und ausgekühlten Buchweizen beigeben, mischen, zu einem weichen, glatten Teig kneten. Teig zugedeckt bei Raumtemperatur ca. 24 Std. aufgehen lassen.",null,null,null,null,null,false],["Teig auf die leicht bemehlte Arbeitsfläche geben. Teig mit dem Teighörnchen ringsum zur Mitte einschlagen. Teig wenden, zu einer Kugel formen. Brot mit der Nahtseite nach unten in ein gut bemehltes Gärkörbchen geben, zugedeckt nochmals ca. 1 Std. aufgehen lassen.",null,null,null,null,null,false],["Brattopf mit dem Deckel in der unteren Hälfte des Ofens einschieben. Ofen auf 240 Grad vorheizen. Nach ca. 20 Min. Brattopf herausnehmen, Topfboden gut bemehlen, Brot aus dem Gärkörbchen kopfüber in den heissen Brattopf stürzen, Deckel aufsetzen.",null,null,null,null,null,false],["Backen: ca. 25 Min. Deckel entfernen. Fertig backen: ca. 15 Min. Herausnehmen, etwas abkühlen, Brot aus dem Brattopf nehmen, auf einem Gitter auskühlen.",null,null,null,null,null,false]]]]],["butter-chicken","gericht","Butter Chicken",null,null,null,10,null,null,["1 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","20 von 23 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Knoblauchzehen",null,0,"5 Knoblauchzehen"],["cm Ingwer",null,0,"5 cm Ingwer"],["Joghurt nature",450.0,0,null],["Madras-Curry",null,0,"2.5 EL"],["Chilipulver",null,0,"2.5 TL"],["Salz",null,0,"2.5 TL"],["Pouletschenkel-Steaks ohne Haut",2000.0,0,null],["Zwiebeln",null,0,"5 Zwiebeln"],["Knoblauchzehen",null,0,"5 Knoblauchzehen"],["cm Ingwer",null,0,"5 cm Ingwer"],["Ghee oder Bratbutter",null,0,"10 EL"],["Kreuzkümmelpulver",null,0,"3.75 TL"],["Korianderpulver",null,0,"3.75 TL"],["Madras-Curry",null,0,"2.5 TL"],["Chilipulver",null,0,"2.5 TL"],["Kardamompulver",null,0,"1.25 TL"],["Zimt",null,0,"1.25 TL"],["Nelkenpulver",null,0,"2.5 Msp"],["gehackte Tomaten (ca. 400 g)",null,0,"2.5 Dose"],["Salz",null,0,"1.88 TL"],["Doppelrahm",500.0,2,"5 dl (1 ml = 1 g)"],["Zucker",null,0,"5 TL"],["Koriande",null,0,"1.25 Bund"]],[["Knoblauch und Ingwer schälen, fein in eine Schüssel reiben. Joghurt, Curry, Chilipulver und Salz daruntermischen. Poulet in ca. 3 cm grosse Stücke schneiden, daruntermischen, zugedeckt im Kühlschrank mind. 1 Std. marinieren.",null,null,null,null,null,false],["Zwiebeln schälen, in feine Streifen schneiden. Knoblauch und Ingwer schälen, fein schneiden.",null,null,null,null,null,false],["2 EL Ghee in einer Bratpfanne heiss werden lassen. Pouletstücke aus der Marinade nehmen, portionenweise je ca. 4 Min. anbraten. Herausnehmen, Hitze reduzieren, restliches Ghee warm werden lassen. Zwiebeln, Knoblauch und Ingwer ca. 3 Min. andämpfen. Kreuzkümmel, Koriander, Curry, Chilipulver, Kardamom, Zimt und Nelkenpulver kurz mitdämpfen. Tomaten beigeben, mischen, salzen, offen bei kleiner Hitze ca. 10 Min. köcheln. Masse in einem Mixglas pürieren zurück in die Pfanne geben, Rahm und Zucker beigeben, aufkochen. Hitze reduzieren, Poulet wieder beigeben, zugedeckt ca. 10 Min. köcheln, offen ca. 5 Min. fertig köcheln. Korianderblättchen abzupfen, darüberstreuen.",null,null,null,null,null,false]]]]],["buerli","komponente","Bürli",null,null,null,null,null,null,["1 von 9 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[["Vorteig",[["Weizensauerteig",10.0,0,"alternativ 0.5g Frischhefe"],["Wasser (handwarm)",120.0,0,null],["Halbweissmehl",120.0,0,"Weizenmehl Type 812"]],[]],["Hauptteig",[["Vorteig",null,0,null],["Ruchmehl",120.0,0,"Weizenmehl Type 1050"],["Halbweissmehl",260.0,0,"Weizenmehl Type 812"],["Wasser (kalt)",270.0,0,null],["Frischhefe",5.0,0,null],["Meersalz",12.0,0,null]],[]],["Zubereitung",[],[["VORTEIG",null,null,null,null,null,false],["Den Sauerteig mit dem Wasser in eine Schüssel geben und gut vermischen. Anschliessend das Mehl dazugeben und alles klumpenfrei verrühren.",null,null,null,null,null,false],["Vorteig abdecken und 1-3 Stunden bei Raumtemperatur gären lassen. Danach den Vorteig bis zu 24 Stunden in den Kühlschrank stellen.",null,null,null,null,null,false],["HAUPTTEIG",null,null,null,null,null,false],["Alle Zutaten in die Küchenmaschine geben und zunächst auf niedriger Stufe 5 Minuten ankneten.",null,null,null,null,null,false],["Nach 10 Minuten die Geschwindigkeit erhöhen und den Teig etwa 4-5 Minuten auf mittlerer Stufe weiterkneten, bis er die Fensterprobe besteht. Sollte der Teig noch klebrig oder reissend sein, einfach weiterkneten, bis er elastisch und dehnbar wird.",null,null,null,null,null,false],["Den Teig in eine leicht gefettete Schüssel legen, abdecken und 5 Stunden bei Raumtemperatur ruhen lassen.",null,null,null,null,null,false],["Während der Ruhezeit den Teig zwei- bis dreimal dehnen und falten. Dazu eine Seite des Teigs anheben, nach aussen dehnen und an die gegenüberliegende Seite der Schüssel legen. Das für alle vier Seiten wiederholen.",null,null,null,null,null,false],["HINWEIS: Da jedes Mehl unterschiedlich reagiert, empfehle ich, etwa 10-15 % des Wassers zurückzubehalten und nach Bedarf hinzuzufügen.",null,null,null,null,null,false],["Tipp: Die Hände vorher in Wasser tauchen, um den Teig leichter handhaben zu können.",null,null,null,null,null,false],["FORMEN",null,null,null,null,null,false],["Den Teig nach der Gärzeit vorsichtig auf eine bemehlte Arbeitsfläche stürzen und in acht 110 g schwere Stücke teilen.",null,null,null,null,null,false],["Ein Teigtuch auf ein Backblech legen und grosszügig mit Mehl bestäuben. Teiglinge vorsichtig zu Kugeln formen und immer zwei aneinander mit der glatten Seite nach oben auf das Teigtuch legen.",null,null,null,null,null,false],["Mit dem Teigtuch zwischen den Teiglingen Falten ziehen, sodass sie sich leicht berühren, aber nicht aneinanderkleben. Teig abdecken und 30-40 Minuten bei Raumtemperatur gären lassen.",null,null,null,null,null,false],["In der Zwischenzeit den Backofen mit einem Brotbackstein oder Pizzablech auf der untersten Schiene auf 230 °C Ober-/Unterhitze vorheizen.",null,null,null,null,null,false],["BACKEN",null,null,null,null,null,false],["Eine Tortenplatte oder einen Brotbackschieber grosszügig mit Mehl bestäuben und die Teiglinge mit dem Verschluss nach oben daraufsetzen. Danach die Teiglinge vorsichtig auf den heissen Brotbackstein oder das heisse Blech im Ofen abschieben.",null,null,null,null,null,false],["Den Ofen bedampfen und die Bürli etwa 20 Minuten backen.",null,null,null,null,null,false],["Nach 20 Minuten die Ofentür öffnen, um den Dampf entweichen zu lassen, und die Bürli weitere 20-25 Minuten knusprig ausbacken.",null,null,null,null,null,false],["Nach dem Backen die Bürli auf einem Gitter vollständig auskühlen lassen.",null,null,null,null,null,false]]]]]]'::jsonb);
select importer.rezepte('[["calamansi-curd","komponente","Calamansi Curd",null,null,null,null,null,null,["4 von 4 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Calamansi 30pcs",null,0,null],["White Sugar 160g",null,0,null],["Egg 2 pcs",null,0,null],["Calamansi Juice 60g",null,0,null]],[]]]],["char-sui-sauce","komponente","Char Sui Sauce",null,null,null,null,null,null,["3 von 9 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Hoisin Sauce",260.0,0,null],["brown Sugar",200.0,0,null],["Chinese Cooking Wine",225.0,0,null],["Honey",285.0,0,null],["light Soy sauce",155.0,0,null],["dark Soy sauce",150.0,0,null],["garlic cloves",null,0,"12 garlic cloves"],["TS Salt",null,0,"4 TS Salt"],["red food coloring",null,0,null]],[]]]],["chees-cake","komponente","Chees Cake",null,null,null,null,null,null,["15 von 19 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[["Boden",[["Butter",100.0,0,null],["Eigelbe",null,0,"2 Eigelbe"],["Glas Zucker (ich brauche Rohrzucker)",null,0,"3/4 Glas Zucker (ich brauche Rohrzucker)"],["Saft einer 1/2 Zitrone",null,0,null],["Mandelessenz (oder Vanille oder Tonkabohne ;-))",null,0,null],["Gläser Mehl (ich brauche halbweisses)",null,0,"2 Gläser Mehl (ich brauche halbweisses)"],["Backpulver - zuerst mit Mehl mischen",null,0,"2 TL"]],[]],["Füllung",[["Quark (kein Magerquark!!! ich brauche das 3/4 Fett bio Quark von Coop)",500.0,0,null],["Eier",null,0,"4 Eier"],["Glas Zucker",null,0,"1 Glas Zucker"],["Glas Rahm",null,0,"1 Glas Rahm"],["Butter",50.0,0,null],["Saft einer Zitrone",null,0,null],["Vanilleessenz (auch hier würde sich die Essenz der Tonkabohne wahrscheinlich gut eignen)",null,0,"1 TL"],["Mehl",null,0,"5 EL"],["Backpulver",null,0,"1 TL"],["Rosinen - Mehl mit Bakpulver und dann mit Rosinen mischen - und erst am Schluss den restlichen Zutaten beigeben (so verteilen sich die Rosinen besser und sinken nicht).",75.0,0,null],["Auf den Teigboden giessen und bei 180°C 45-60 Minuten backen.",null,0,null],["...en Guete :-)",null,0,null]],[]],["Zubereitung",[],[["=> Alles mischen, in eine runde Backform legen und bei 180°C backen bis Teig goldig.",null,null,null,null,null,false],["=> Alle Zutaten mischen, dann",null,null,null,null,null,false],["Auf den Teigboden giessen und bei 180°C 45-60 Minuten backen.",null,null,null,null,null,false],["...en Guete :-)",null,null,null,null,null,false]]]]],["chicken-katsu-curry","komponente","Chicken Katsu Curry",null,null,null,null,null,null,["1 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","10 von 11 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["vegetable oil",null,0,"1 tablespoon"],["onion, peeled & chopped",null,0,"1 onion, peeled & chopped"],["garlic clove, peeled",null,0,"1 garlic clove, peeled"],["carrot, peeled & chopped",null,0,"1 carrot, peeled & chopped"],["plain flour",null,0,"4 tablespoons"],["curry powder",null,0,"2 tablespoon"],["chicken stock",600.0,2,"600 ml (1 ml = 1 g)"],["soy sauce",null,0,"1 tablespoon"],["honey",null,0,"2 teaspoons"],["garam masala",null,0,"½ teaspoon"],["tomatosauce",null,0,"3 tablespoons; 2 teaspoon xantana"]],[]]]],["chicken-riggies","komponente","Chicken Riggies",null,null,null,null,null,null,["4 von 13 Zutaten ohne Gra