über schwacher Hitze",null,null,null,null,null,false],["schmoren, bis die Masse duftet und ein bisschen ölig ist. Mit Palmzucker und",null,null,null,null,null,false],["Fischsauce würzen und vom Herd nehmen. Abkühlen lassen. Die Garnelen",null,null,null,null,null,false],["dazugeben.",null,null,null,null,null,false],["Diese Mischung in ein Bananenblatt einpacken und gut verschliessen.",null,null,null,null,null,false],["10 Minuten bei mittlerer Hitze grillieren.",null,null,null,null,null,false]]]]],["general-tsos-chicken","komponente","General Tso’s Chicken",null,null,null,null,null,null,["8 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","13 von 25 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[["Marinade",[["grosses Eiweiss",null,0,"1 grosses Eiweiss"],["chinesische dunkle Sojasauce",30.0,2,"30 ml (1 ml = 1 g)"],["Shaoxing-Wein; gibt''s im Asia-Shop",30.0,2,"30 ml (1 ml = 1 g)"],["Wodka",30.0,2,"30 ml (1 ml = 1 g)"],["Maizena",null,0,"3 EL"],["Backpulver",null,0,"1/4 TL"]],[]],["Geflügel",[["Pouletschenkel, entbeint und ohne Haut, in 2-3 cm grosse Stücke zerteilt",500.0,0,null]],[]],["Panade",[["Weissmehl",70.0,0,null],["Maizena",70.0,0,null],["Backpulver",null,0,"1/2 TL"],["Salz",null,0,"1/2 TL"]],[]],["Frittieröl",[["Erdnuss- oder Rapsöl zum Frittieren",1500.0,2,"1 1/2 l (1 ml = 1 g)"]],[]],["Sauce",[["Kristallzucker",50.0,0,null],["Hühnerbouillon",80.0,2,"80 ml (1 ml = 1 g)"],["dunkle Sojasauce",null,0,"3 EL"],["Shaoxing-Wein; gibt''s im Asia-Shop",30.0,2,"30 ml (1 ml = 1 g)"],["Mirin-Reisessig",30.0,2,"30 ml (1 ml = 1 g)"],["Sesamöl",null,0,"1 TL"],["Maizena",null,0,"1 EL"]],[]],["Ausbacken",[["Erdnuss- oder Rapsöl",10.0,2,"10 ml (1 ml = 1 g)"],["Knoblauchzehen, fein gehackt",null,0,"2 Knoblauchzehen, fein gehackt"],["frischer Ingwer, fein gehackt",null,0,"2 TL"],["Frühlingszwiebeln, weisse und grüne Teile getrennt grob geschnitten",null,0,"6 Frühlingszwiebeln, weisse und grüne Teile getrennt grob geschnitten"],["mittelscharfe, rote Peperoncini, fein gehackt",null,0,"8 mittelscharfe, rote Peperoncini, fein gehackt"]],[]],["Reis",[["Jasminreis, gekocht, zum Servieren",null,0,null]],[]]]],["gerstensuppe","gericht","Gerstensuppe",null,null,null,10,null,null,["2 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","4 von 11 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Butter",null,0,"2.5 EL"],["Zwiebel, fein gehackt",null,0,"2.5 Zwiebel, fein gehackt"],["Sellerie, in Würfeli",375.0,0,null],["Pfälzer Rüebli, in Würfeli",250.0,0,null],["Rüebli, in Würfeli",250.0,0,null],["Bündnerfleisch, in Würfeli",125.0,0,null],["Rollgerste",200.0,0,null],["Fleischbouillon",2500.0,2,"2.5 l (1 ml = 1 g)"],["Salz, Pfeffer, nach Bedarf",null,0,null],["Rahm",500.0,2,"5 dl (1 ml = 1 g)"],["Schnittlauch, fein geschnitten",null,0,"7.5 EL"]],[["Butter in einer grossen Pfanne warm werden lassen. Zwiebel, Sellerie, Rüebli und Bündnerfleisch andämpfen. Rollgerste beigeben, kurz mitdünsten.",null,null,null,null,null,false],["Bouillon dazugiessen, aufkochen, Hitze reduzieren, zugedeckt bei kleiner Hitze ca. 40 Min. köcheln, würzen.",null,null,null,null,null,false],["Die Hälfte des Rahms dazugiessen, Suppe nur noch heiss werden lassen. Restlichen Rahm halb steif schlagen, darauf verteilen, Schnittlauch darüberstreuen.",null,null,null,null,null,false]]]]],["geschnetzeltes-zuercher-art","gericht","Geschnetzeltes Zürcher Art",null,"Chicken",null,10,null,null,["Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Fleisch",1400.0,0,null],["Mehl",20.0,0,null],["Öl",75.0,0,null],["Gewürzmischung",15.0,0,null],["Butter",80.0,0,null],["Zwiebeln",80.0,0,null],["Champignons",500.0,0,null],["Weisswein",300.0,0,null],["Demiglace",400.0,0,null],["Rahm",300.0,0,null],["Peterli",10.0,0,null]],[]]]],["ginger-scalion-sauce","komponente","Ginger-Scalion Sauce",null,null,null,null,null,null,["18 von 18 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["g",null,0,"100 g"],["Scallion(s), (6 scallions) thinly sliced",null,0,null],["g",null,0,"50 g"],["Fresh ginger root, (3-inch piece) peeled and minced",null,0,null],["g",null,0,"4 g"],["White pepper, ground (2 teaspoons)",null,0,null],["g",null,0,"3 g"],["Kosher salt, (1 teaspoon)",null,0,null],["g",null,0,"2 g"],["Sand ginger, dried (2 small pieces; see \"Before we begin\" note), finely ground in a spice grinder",null,0,null],["g",null,0,"1 g"],["Sugar, (1/4 teaspoon)",null,0,null],["g",null,0,"85 g"],["Neutral oil",null,0,null],["g",null,0,"10 g"],["Light Chinese soy sauce",null,0,null],["g",null,0,"5 g"],["Toasted sesame oil, (1 teaspoon)",null,0,null]],[]]]],["glasnudelsalat","komponente","Glasnudelsalat",null,null,null,null,null,null,["12 von 15 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Glasnudeln",100.0,0,null],["Pouletbrust, fein gehackt",200.0,0,null],["wenig Limettensaft",null,0,null],["Mu-Err Pilze frisch oder eingeweicht",100.0,0,null],["Gurke klein",null,0,"1 Gurke klein"],["Peperoni",null,0,"1 Peperoni"],["Schalotten",null,0,"2 Schalotten"],["2",null,0,"2"],["Frühlingszwiebeln",null,0,null],["EL",null,0,"1 EL"],["gehackte Erdnüsse",null,0,null],["Fischsauce",null,0,"8 EL"],["Limettensaft",null,0,"8 EL"],["Zucker",null,0,"4 EL"],["Chili, Pfefferminze",null,0,null]],[["Glasnudeln in kalten Wasser min. 10 Minuten einlegen. Kurz kochen und mit",null,null,null,null,null,false],["kaltem Wasser abschrecken. Pouletbrust mit wenig Limettensaft und Wasser ohne",null,null,null,null,null,false],["Öl braten. Pilze fein schneiden. Gemüse in feine Würfel schneiden.",null,null,null,null,null,false],["Fischsace, Limettensaft und Zucker vermischen und etwas erwärmen damit der",null,null,null,null,null,false],["Zucker sich auflöst. Mit den Poulet und dem Gemüse mischen. Nach Belieben",null,null,null,null,null,false],["Chili dazugeben. Nudeln auf einem Teller anrichten. Den Salat darauf anrichten",null,null,null,null,null,false],["und mit Pfefferminze und Erdnüssen garnieren.",null,null,null,null,null,false]]]]],["glasnudelsalat-2","komponente","Glasnudelsalat",null,"Chicken, Thai",null,null,null,null,["10 von 13 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Glasnudeln",100.0,0,null],["Pouletbrust, fein gehackt",200.0,0,null],["wenig Limettensaft",null,0,null],["Mu-Err Pilze frisch oder eingeweicht",100.0,0,null],["Gurke klein",null,0,"1 Gurke klein"],["Peperoni",null,0,"1 Peperoni"],["Schalotten",null,0,"2 Schalotten"],["Frühlingszwiebeln",null,0,"2 Frühlingszwiebeln"],["gehackte Erdnüsse",null,0,"1 EL"],["Fischsauce",null,0,"8 EL"],["Limettensaft",null,0,"8 EL"],["Zucker",null,0,"4 EL"],["Chili, Pfefferminze",null,0,null]],[["Glasnudeln in kalten Wasser min. 10 Minuten einlegen. Kurz kochen und mit",null,null,null,null,null,false],["kaltem Wasser abschrecken. Pouletbrust mit wenig Limettensaft und Wasser ohne",null,null,null,null,null,false],["Öl braten. Pilze fein schneiden. Gemüse in feine Würfel schneiden.",null,null,null,null,null,false],["Fischsace, Limettensaft und Zucker vermischen und etwas erwärmen damit der Zucker sich auflöst. Mit den Poulet und dem Gemüse mischen. Nach Belieben Chili dazugeben. Nudeln auf einem Teller anrichten. Den Salat darauf anrichten und mit Pfefferminze und Erdnüssen garnieren.",null,null,null,null,null,false]]]]],["grilling-elixir-1","komponente","Grilling Elixir 1",null,null,null,null,null,null,["Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Molasses",60.0,0,null],["Clover honey",90.0,0,null],["Worcestershire sauce",150.0,0,null],["Wright’s hickory liquid smoke",35.0,0,null]],[["The Maillard reaction is the ultimate flavor-creating reaction that occurs during cooking. It begins as a simple interaction between the amino acids and sugars found in all protein-rich foods, but quickly becomes more elaborate as molecules continue reacting in more complex ways. These chain reactions generate hundreds of new aromatic molecules that make food smell delicious—the characteristics of roasting meat, grilling fish, baking bread, and sizzling bacon.",null,null,null,null,null,false],["The Maillard reaction occurs noticeably above 266 °F / 130 °C and speeds up as temperatures reach 356 °F / 180 °C. Above those temps, pyrolysis—(or burning)—occurs, resulting in charred, bitter flavors. Conversely, the reaction slows to a crawl below 266 °F / 130 °C. A reaction that happens in minutes at 302 °F / 150 °C can take hours at 248 °F / 120 °C or even weeks at 140 °F / 60 °C.",null,null,null,null,null,false],["One way to accelerate the Maillard reaction is to change the amount of “reducing sugars” (things like glucose, fructose, lactose, maltose, and more exotic sugars like ribose) and the availability of amino acids on the surface of the food. Adding one of these reducing sugars to the surface of food will accelerate and intensify the reaction—even at lower temperatures—improving the flavor profile.",null,null,null,null,null,false],["Combine the molasses and honey in a microwave safe bowl or glass liquid measuring cup. Microwave on high for 15 seconds. This will warm the syrups up just enough to make them more fluid and easier to mix with the other ingredients.Add the remaining ingredients to your warmed sugars and stir well to combine. Then transfer the elixir into your spray bottle.",null,null,null,null,null,false],["This grilling elixir is amazing on any cut of meat or veggie where you want to add a deeper flavor and color. It adds a pleasant marinade flavor fast, and the sugars help the crust develop faster when you’re finishing meats (that were already cooked sous vide) hot and fast on the grill.",null,null,null,null,null,false],["One of our favorite ways to use the elixir is to spray it directly on our BBQ grates right before adding the meat. It’s excellent on chicken, as a wet mop when grilling, and it helps dry rubs adhere. Layer it on for max flavor and textural impact! (Spray > rub > spray > rub)",null,null,null,null,null,false],["Beyond the grill, anything that you pull out of your oven or off the stovetop is a good candidate for the elixir. Juicy, sticky, fatty, or roasted meats will readily soak up this sweet-smoky goodness. We recommend that you avoid spraying on foods that need to stay crispy.",null,null,null,null,null,false]]]]],["grilling-elixir-2","komponente","Grilling Elixir 2",null,null,null,null,null,null,["Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Apple cider vinegar",150.0,0,null],["Apple juice",300.0,0,null],["Liquid smoke",12.0,0,null],["Honey",300.0,0,null],["Lemon peel",6.0,0,null],["Thyme",9.0,0,null],["Lemon juice, fresh",150.0,0,null],["Black peppercorn, crushed",3.0,0,null]],[["In a quart jar, add the honey, liquid smoke, apple juice, and apple cider vinegar and mix well to combine. Add the thyme, black peppercorn, and lemon peel.",null,null,null,null,null,false],["Let steep at room temperature overnight (up to 12 hours) to allow the flavors to fully extract and come together.",null,null,null,null,null,false],["In a hurry? If you’re crunched for time, you can expedite the steep. Combine all the ingredients in a small pan and bring to a simmer. Turn off the heat, cover with a lid, and let the mixture sit for 15 minutes.",null,null,null,null,null,false],["After steeping, add the fresh squeezed lemon juice to the mixture and stir to combine.",null,null,null,null,null,false],["Then strain the mixture using a coffee filter or other fine filter. This will ensure that no large particles get left behind that may clog up your spray bottle.",null,null,null,null,null,false],["Transfer the mixture to a glass spray bottle.",null,null,null,null,null,false],["Spritz on white meats, tofu, seafood, and veggies just before hitting the grill. As a light refresher, spray on near the end of the cooking, focusing on areas that have extra bits of charring to mellow and brighten up those burnt flavors.",null,null,null,null,null,false],["Pair with Elixir 1 for the ultimate grilling one-two flavor punch.",null,null,null,null,null,false]]]]],["gruene-minestrone","gericht","Grüne Minestrone",null,null,null,10,null,null,["1 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","4 von 8 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Bundzwiebeln mit dem Grün",null,0,"15 Bundzwiebeln mit dem Grün"],["Kohlrabi",null,0,"5 Kohlrabi"],["Öl",null,0,"2.5 EL"],["Gemüsebouillon",2500.0,2,"2.5 l (1 ml = 1 g)"],["Teigwaren (z. B. Spiralen)",125.0,0,null],["tiefgekühlte Erbsli",500.0,0,null],["Salz, Pfeffer, nach Bedarf",null,0,null],["geriebener Käse",100.0,0,null]],[["Bundzwiebeln fein schneiden, Grün beiseite legen. Kohlrabi schälen, in Stängeli schneiden. Öl in einer Pfanne warm werden lassen. Zwiebeln und Kohlrabi ca. 2 Min. andämpfen.",null,null,null,null,null,false],["Bouillon dazugiessen, Teigwaren und Erbsli beigeben, aufkochen. Hitze reduzieren, Teigwaren knapp al dente kochen. Beiseite gestelltes Bundzwiebelgrün beigeben, heiss werden lassen, würzen.",null,null,null,null,null,false],["Suppe anrichten, Käse darüberstreuen.",null,null,null,null,null,false]]]]],["guga-sauce","komponente","Guga sauce",null,null,null,null,null,null,["Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["mayonnaise",440.0,0,null],["ketchup",235.0,0,null],["mustard",130.0,0,null],["onion powder",4.7,0,null]],[]]]],["gulaschsuppe","komponente","Gulaschsuppe",null,null,null,null,null,null,["3 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","2 von 14 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Rindergulasch, ca. 2 cm gewürfelt",2000.0,0,null],["Zwiebeln, gewürfelt",500.0,0,null],["Paprika rot, gewürfelt",500.0,0,null],["Kartoffeln, gewürfelt",500.0,0,null],["Knoblauch, fein gehackt",50.0,0,null],["Kümmel, fein gehackt",3.0,0,null],["Zitronenabrieb",3.0,0,null],["Majoranblätter frisch, fein geschnitten",null,0,"2 EL"],["Rotwein",1000.0,2,"1 l (1 ml = 1 g)"],["Tomatenmark",50.0,0,null],["Paprikapulver",10.0,0,null],["Rinderfond",2000.0,2,"2 l (1 ml = 1 g)"],["Öl",20.0,2,"20 ml (1 ml = 1 g)"],["Salz, Pfeffer",null,0,null]],[["Nach dem Vorheizen braten Sie das Fleisch und die Zwiebeln an, rösten",null,null,null,null,null,false],["das Tomatenmark und das Paprikapulver etwas mit und löschen ab mit dem",null,null,null,null,null,false],["Rotwein. Lassen Sie diesen etwas reduzieren und füllen Sie dann mit dem",null,null,null,null,null,false],["Rinderfond auf. Geben Sie die Kartoffeln, die Kräuter und die Gewürze",null,null,null,null,null,false],["dazu. Anschliessend legen Sie den Kerntemperaturfühler in die Flüssigkeit",null,null,null,null,null,false],["und schliessen den Deckel. Nach Ablauf der Garzeit wählen Sie die",null,null,null,null,null,false],["Funktion \"Weiter mit Zeit\" und stellen für die Paprika weitere acht",null,null,null,null,null,false],["Minuten ein. Möchten Sie die Suppe am Ende noch abbinden, nutzen Sie",null,null,null,null,null,false],["dazu die Funktion \"Aufkochen\".",null,null,null,null,null,false]]]]],["gurkenrelish","komponente","Gurkenrelish",null,null,null,null,null,null,["7 von 8 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Reisessig",null,0,"3 EL"],["Zucker",null,0,"3 EL"],["Wasser",null,0,"4 EL"],["Salz",null,0,"1 Prise"],["Gurken, vierteln und in feine Scheiben schneiden",200.0,0,null],["Schalotten, in feine Streifen schneiden",null,0,"4 Schalotten, in feine Streifen schneiden"],["grosse rote Chili, in feine Streifen schneiden",null,0,"1 grosse rote Chili, in feine Streifen schneiden"],["wenig Koriander",null,0,null]],[["Essig, Zucker, Wasser und Salz in einer kleinen Pfanne aufkochen. Wenn sich der",null,null,null,null,null,false],["Zucker gelöst hat, vom Feuer nehmen. Die restlichen Zutaten in eine Schüssel",null,null,null,null,null,false],["geben und mit dem Sirup übergiessen. Das Relish wird besser, wenn es",null,null,null,null,null,false],["mindestens eine Stunde ziehen kann und ist in Kühlschrank bis eine Woche",null,null,null,null,null,false],["haltbar.",null,null,null,null,null,false]]]]],["gurkenrelish-2","komponente","Gurkenrelish",null,"Thai",null,null,null,null,["6 von 7 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Reisessig",null,0,"3 EL"],["Zucker",null,0,"3 EL"],["Wasser",null,0,"4 EL"],["Salz",null,0,"1 Prise"],["Gurken, vierteln und in feine Scheiben schneiden",200.0,0,null],["Schalotten, in feine Streifen schneiden",null,0,"4 Schalotten, in feine Streifen schneiden"],["grosse rote Chili, in feine Streifen schneiden wenig Koriander",null,0,"1 grosse rote Chili, in feine Streifen schneiden wenig Koriander"]],[["Essig, Zucker, Wasser und Salz in einer kleinen Pfanne aufkochen. Wenn sich der Zucker gelöst hat, vom Feuer nehmen. Die restlichen Zutaten in eine Schüssel geben und mit dem Sirup übergiessen. Das Relish wird besser, wenn es mindestens eine Stunde ziehen kann und ist in Kühlschrank bis eine Woche haltbar.",null,null,null,null,null,false]]]]],["hausdressing","komponente","Hausdressing",null,null,null,null,null,null,["2 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","12 von 14 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["ZUTATEN (ergibt rund 6 dl)",null,0,null],["Zwiebel",null,0,"¼ Zwiebel"],["Knoblauchzehe",null,0,"1 Knoblauchzehe"],["Bouillon",150.0,2,"150 ml (1 ml = 1 g)"],["Ei",null,0,"1 Ei"],["Balsamico bianco",75.0,2,"75 ml (1 ml = 1 g)"],["dl Rapsöl",null,0,"3–4 dl Rapsöl"],["Tabasco, ca. 4 Spritzer",null,0,null],["Worcestershire, 3 Spritzer",null,0,null],["Salz nach Geschmack",null,0,null],["Pfeffer, 6 Umdrehungen",null,0,null],["etwas Aromat (für meine Chemie-Kämpfer 😏)",null,0,null],["Büschel Petersilie",null,0,"1 Büschel Petersilie"],["grobkörniger Senf",nu