,0,"2 El"],["zucker",null,0,"2 El"]],[]]]],["kartoffel-wein-suppe","gericht","Kartoffel-Wein-Suppe",null,null,null,10,null,null,["3 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","6 von 12 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Zwiebel",null,0,"2.5 Zwiebel"],["Knoblauchzehe",null,0,"2.5 Knoblauchzehe"],["mehlig kochende Kartoffeln",1250.0,0,null],["Olivenöl",null,0,"2.5 EL"],["Weisswein",625.0,2,"6.25 dl (1 ml = 1 g)"],["glutenfreie Gemüsebouillon",2000.0,2,"20 dl (1 ml = 1 g)"],["Rahm",500.0,2,"5 dl (1 ml = 1 g)"],["Salz, Pfeffer, nach Bedarf",null,0,null],["Pinienkerne",100.0,0,null],["getrocknete Cranberrys",100.0,0,null],["glattblättrige Petersilie",null,0,"1.25 Bund"],["Olivenöl",null,0,"3.75 EL"]],[["Zwiebel, Knoblauch und Kartoffeln schälen, in Stücke schneiden.",null,null,null,null,null,false],["Öl in einer Pfanne warm werden lassen. Zwiebel und Knoblauch ca. 2 Min. andämpfen. Kartoffeln ca. 3 Min. mitdämpfen. Wein dazugiessen, auf die Hälfte einkochen. Bouillon dazugiessen, aufkochen. Hitze reduzieren, zugedeckt ca. 15 Min. köcheln, bis die Kartoffeln weich sind. Rahm dazugiessen, Suppe pürieren, würzen.",null,null,null,null,null,false],["Pinienkerne und Cranberrys grob hacken, beides in einer Bratpfanne ohne Fett ca. 2 Min. rösten. Petersilie fein schneiden, mit dem Öl mischen. Heisse Suppe anrichten, Cranberry-Streusel und Petersilienöl darauf verteilen.",null,null,null,null,null,false]]]]]]'::jsonb);
