gt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Gemüsepapaya",null,0,"1 Gemüsepapaya"],["Zehen Knoblauch",null,0,"2 Zehen Knoblauch"],["Chili",null,0,"2 - 3 Chili"],["Erdnüsse",null,0,"2 EL"],["lange Bohnen",null,0,"4 lange Bohnen"],["Tomaten, in Würfel geschnitten",null,0,"2 Tomaten, in Würfel geschnitten"],["Fischsauce",null,0,"2 EL"],["Limettensaft",null,0,"2 EL"],["Zucker",null,0,"1 EL"]],[["Die Papaya waschen und schälen, in feinste Streifen schneiden. Knoblauch, Chilis",null,null,null,null,null,false],["und Erdnüsse im Mörser leicht zerdrücken. Die Bohnen in ca. 3 cm lange Stücke",null,null,null,null,null,false],["schneiden und ebenfalls im Mörser leicht zerdrücken.",null,null,null,null,null,false],["Die Fischsauce mit dem Limettensaft und den Zucker mischen und etwas",null,null,null,null,null,false],["erwärmen, damit der Zucker sich auflöst.",null,null,null,null,null,false],["Die Papayastreifen zu den gemörserten Zutaten geben und mit der Sauce gut",null,null,null,null,null,false],["mischen. Am Schluss die Tomatenwürfel dazugeben und anrichten.",null,null,null,null,null,false],["Dazu passen Riesencrevetten vom Grill. Als Variante kann der Salat auch mit",null,null,null,null,null,false],["grünen Mangos zubereitet werden",null,null,null,null,null,false]]]]],["som-tam-2","komponente","Som Tam",null,"Spicy, Thai",null,null,null,null,["9 von 9 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Gemüsepapaya",null,0,"1 Gemüsepapaya"],["Zehen Knoblauch",null,0,"2 Zehen Knoblauch"],["Chili",null,0,"2 - 3 Chili"],["Erdnüsse",null,0,"2 EL"],["lange Bohnen",null,0,"4 lange Bohnen"],["Tomaten, in Würfel geschnitten",null,0,"2 Tomaten, in Würfel geschnitten"],["Fischsauce",null,0,"2 EL"],["Limettensaft",null,0,"2 EL"],["Zucker",null,0,"1 EL"]],[["Die Papaya waschen und schälen, in feinste Streifen schneiden. Knoblauch, Chilis und Erdnüsse im Mörser leicht zerdrücken. Die Bohnen in ca. 3 cm lange Stücke schneiden und ebenfalls im Mörser leicht zerdrücken.",null,null,null,null,null,false],["Die Fischsauce mit dem Limettensaft und den Zucker mischen und etwas erwärmen, damit der Zucker sich auﬂöst.",null,null,null,null,null,false],["Die Papayastreifen zu den gemörserten Zutaten geben und mit der Sauce gut mischen. Am Schluss die Tomatenwürfel dazugeben und anrichten.",null,null,null,null,null,false]]]]],["spaetzli","gericht","Spätzli",null,null,null,8,null,null,["1 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","2 von 5 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Mehl",400.0,0,null],["Spätzlimehl",200.0,0,null],["Milchwasser",300.0,2,"3 dl (1 ml = 1 g)"],["Eier",null,0,"6 Eier"],["Salz",null,0,"1.5 TL"]],[]]]],["spinat-raita","gericht","Spinat Raita",null,"Indian",null,4,null,null,["2 von 4 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Spinat",350.0,0,null],["Joghurt",500.0,0,null],["Knoblauchzehen gehackt",null,0,"2 Knoblauchzehen gehackt"],["Salz, Pfeffer",null,0,null]],[["Den Spinat waschen und nass in einen grossen Topf geben. Zugedeckt bei milder Hitze 3 - 5 Minuten garen, bis er zusammengefallen ist. Den Spinat in ein Sieb geben und sorgfältig das Wasser herauspressen. Das Joghurt mit dem Knoblauch glatt rühren und mit Salz und Pfeffer abschmecken. Den Spinat daruntermischen und kalt stellen.",null,null,null,null,null,false]]]]],["spinat-lasagne","gericht","Spinat-Lasagne",null,null,null,6,null,null,["2 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","15 von 23 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Öl zum Braten",null,0,null],["Hackfleisch (Poulet)",600.0,0,null],["Salz",null,0,"0.75 TL"],["wenig Cayennepfeffer",null,0,null],["Zwiebel",null,0,"1 Zwiebel"],["Knoblauchzehen",null,0,"2 Knoblauchzehen"],["tiefgekühlter Blattspinat, aufgetaut",1000.0,0,null],["Salz",null,0,"0.75 TL"],["wenig Cayennepfeffer",null,0,null],["Butter",40.0,0,null],["Mehl",40.0,0,null],["Milch",800.0,2,"8 dl (1 ml = 1 g)"],["Muskat",null,0,"0.25 TL"],["Salz",null,0,"0.75 TL"],["wenig Pfeffer",null,0,null],["Rollen Pastateig",null,0,"2 Rollen Pastateig"],["geriebener Sbrinz",60.0,0,null],["Jungspinat",50.0,0,null],["gemahlene geschälte Mandeln",null,0,"2 EL"],["Olivenöl",100.0,2,"1 dl (1 ml = 1 g)"],["geriebener Sbrinz",null,0,"2 EL"],["Salz",null,0,"0.25 TL"],["wenig Pfeffer",null,0,null]],[["Wenig Öl in einer beschichteten Bratpfanne heiss werden lassen. Hackfleisch portionenweise je ca. 3 Min. anbraten, herausnehmen, würzen.",null,null,null,null,null,false],["Zwiebel und Knoblauch schälen, beides fein hacken. Wenig Öl in derselben Pfanne warm werden lassen. Zwiebel und Knoblauch ca. 3 Min. andämpfen. Spinat ca. 5 Min. mitdämpfen, würzen. Hackfleisch wieder beigeben.",null,null,null,null,null,false],["Ofen auf 200 Grad vorheizen. Butter in einer Pfanne warm werden lassen. Mehl beigeben, unter Rühren mit dem Schwingbesen dünsten, das Mehl darf dabei keine Farbe annehmen. Pfanne von der Platte nehmen. Milch auf einmal dazugiessen, unter Rühren aufkochen, Hitze reduzieren, würzen. Sauce unter gelegentlichem Rühren bei mittlerer Hitze ca. 10 Min. köcheln, bis sie sämig ist.",null,null,null,null,null,false],["Pastateige entrollen, quer halbieren. 1/5 der Spinat-Hackfleisch-Masse in der vorbereiteten Form verteilen. Teige, Spinatmasse und Béchamelsauce lagenweise in die Form schichten, mit Béchamelsauce abschliessen. Käse darüberstreuen.",null,null,null,null,null,false],["Backen: ca. 35 Min. in der Mitte des Ofens.",null,null,null,null,null,false],["Spinat in einen Messbecher geben, Mandeln beigeben. Die Hälfte des Öls dazugiessen, nicht zu fein pürieren. Restliches Öl und Käse darunterrühren, würzen. Spinat-Pesto auf der Lasagne verteilen, anrichten.",null,null,null,null,null,false]]]]],["sriracha","komponente","Sriracha",null,null,null,null,null,null,["4 von 8 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Chilis",450.0,0,null],["Wasser",250.0,0,null],["Reisessig",200.0,0,null],["Zucker",null,0,"1 Tl"],["Palmzucker",null,0,"1 Tl"],["Zehen Knoblauch",null,0,"8 Zehen Knoblauch"],["% Salz",null,0,"2 % Salz"],["Xantan",2.0,0,null]],[]]]],["stocki","komponente","Stocki",null,null,null,null,null,null,["2 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Wasser",1800.0,2,"1.8 L (1 ml = 1 g)"],["Butter",80.0,0,null],["Salz",20.0,0,null],["Milch",1200.0,2,"1.2 l (1 ml = 1 g)"]],[]]]],["super-umami-ramen-broth-in-less-than-20-minutes","komponente","Super Umami Ramen Broth in Less Than 20 Minutes",null,null,null,null,null,null,["1 von 8 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Water",2000.0,0,null],["Baking soda",5.0,0,null],["Kombu",30.0,0,null],["Scallions",125.0,0,null],["Fresh ginger",100.0,0,null],["Garlic cloves",30.0,0,null],["Soy sauce",120.0,0,null],["Chicken",null,0,null]],[["Our goal here is to get the maximum extraction of flavor as efficiently as we can, which is why we are using the pressure cooker and the baking soda. But one more way to get all the flavor out of those veggies is to slice them thinly to maximize their surface area—this helps the water pull out the flavor even faster.",null,null,null,null,null,false],["If you are going to include meat, we recommend adding some chicken wings to the broth or some pork bones with a bit of white miso and mirin.",null,null,null,null,null,false],["Simply include these ingredients with the rest of your veggies in the beginning and stick to the same cooking time and high-pressure level. Once all of your ingredients have been added to the pressure cooker, lock down the lid and cook for 15 minutes at high-pressure, starting the timer once you are up to pressure. After 15 minutes of cooking at high-pressure, remove the pot from the heat and let it depressurize before removing the lid.",null,null,null,null,null,false],["If you''re ready to eat…",null,null,null,null,null,false],["85 g Shiitake mushrooms",null,null,null,null,null,false],["Strain the broth into a saucepan. Bring the broth up to a simmer, add in the whole shiitake mushrooms and gently simmer for about two minutes.",null,null,null,null,null,false]]]]],["super-buerli","komponente","Super-Bürli",null,null,null,null,null,null,["2 von 11 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[["Vorteig",[["Wasser",100.0,0,null],["Halbweissmehl",50.0,0,null],["Weizenvolkornmehl",50.0,0,null],["Sauerteig",5.0,0,null]],[]],["Autolyse-Vorteig",[["Halbweissmehl",210.0,0,null],["Wasser",120.0,0,null]],[]],["Hauptteig",[["Vorteig",null,0,null],["Autolyse-Vorteig",null,0,null],["Frischhefe",3.0,0,null],["Salz",7.0,0,null],["Wasser",35.0,0,null]],[]]]],["swee-chilli-sauce-2","komponente","Swee Chilli Sauce 2",null,null,null,null,null,null,["8 von 11 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Knoblauchzehen",null,0,"10 Knoblauchzehen"],["grosse rote Chilis",null,0,"4 grosse rote Chilis"],["Ingwer",100.0,0,null],["Galangal",30.0,0,null],["Kaffir-Limettenblätter",null,0,"8 Kaffir-Limettenblätter"],["Stängel Zitronengras",null,0,"3 Stängel Zitronengras"],["Koriander",null,0,"1 Bund"],["Zucker",150.0,0,null],["Apfelessig",null,0,"7 EL"],["Fischsauce",null,0,"4 EL"],["Sojasauce",null,0,"4 EL"]],[["Ingwer und Galangal schälen und grob hacken. Beim Zitronengras äussere Blätter entfernen, dann oberes Drittel abscheiden und wegwerfen. Den Rest grob hacken. Koriander grob hacken.",null,null,null,null,null,false],["Zusammen mit Knoblauch, Chilis, Limettenblätter und Koriander in einem Cutter zu einer feinen Paste zerkleinern.",null,null,null,null,null,false],["Zucker in einem schweren Topf erhitzen, flüssig werden lassen und köcheln, bis er dunkel wird (Achtung: nicht verbrennen lassen!).",null,null,null,null,null,false],["Gewürzpaste einrühren, erneut zum Kochen bringen und Apfelessig, Fisch- und Sojasauce beigeben. 1 Minute köcheln lassen, abkühlen und gekühlt aufbewahren, sie hält wochenlang.",null,null,null,null,null,false]]]]],["sweet-chilli-sauce","komponente","Sweet Chilli Sauce",null,null,null,null,null,null,["3 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["- 1kg Sugar",850.0,0,null],["Chillies",100.0,0,null],["Fish Sauce",100.0,2,"100 ml (1 ml = 1 g)"],["Rice Wine Vinegar",850.0,2,"850 ml (1 ml = 1 g)"],["Water",570.0,2,"570 ml (1 ml = 1 g)"],["Garlic",120.0,0,null],["Xanthan Gum",3.0,0,null]],[]]]],["taboule","komponente","Taboulé",null,null,null,null,null,null,["1 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","8 von 12 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Olivenöl",null,0,"0.5 EL"],["Couscous",150.0,0,null],["Wasser",250.0,2,"2.5 dl (1 ml = 1 g)"],["TLSalz",null,0,"0.5 TLSalz"],["Bio-Zitrone",null,0,"1 Bio-Zitrone"],["Olivenöl",null,0,"5 EL"],["Salz, Pfeffer, nach Bedarf",null,0,null],["Bundzwiebeln mit dem Grün",null,0,"2 Bundzwiebeln mit dem Grün"],["Gurke",null,0,"0.5 Gurke"],["Tomaten",null,0,"2 Tomaten"],["glattblättrige Petersilie",20.0,0,null],["Pfefferminze",20.0,0,null]],[["Öl in einer Pfanne warm werden lassen. Bulgur beigeben, unter Rühren kurz dünsten. Wasser dazugiessen, aufkochen, salzen, zugedeckt bei kleiner Hitze ca. 5 Min. köcheln. Pfanne von der Platte nehmen, ca. 5 Min. stehen lassen. Bulgur mit einer Gabel lockern, etwas abkühlen.",null,null,null,null,null,false],["Von der Zitrone Schale dazureiben, Saft dazupressen. Öl beigeben, mischen, würzen.",null,null,null,null,null,false],["Bundzwiebeln in feine Ringe schneiden. Gurke vierteln, in Stücke, Tomaten in Würfeli schneiden. Petersilie und Pfefferminze fein schneiden, alles unter den Bulgur mischen.",null,null,null,null,null,false]]]]],["teig-fuer-artisan-pizza","gericht","Teig für Artisan Pizza",null,null,null,3,null,null,["Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[["Poolish",[["Mehl",75.0,0,null],["Wasser",75.0,0,null],["Trockenhefe",0.08,0,null]],[]],["Teig",[["Wasser",375.0,0,null],["Trockenhefe",2.6,0,null],["Mehl",550.0,0,null],["Papain",0.06,0,null],["Malzpulver",13.0,0,null],["Salz",12.5,0,null],["Olivenöl",20.0,0,null]],[]],["Zubereitung",[],[["Poolish 12 - 16 h bei Raumtemperatur gehen lassen",null,null,null,null,null,false],["Wasser, Hefe und Poolish mischen.",null,null,null,null,null,false],["Mehl und Malz zugeben und gut vermischen.",null,null,null,null,null,false],["Bis zu mittlerer Glutenentwicklung kneten",null,null,null,null,null,false],["Salz zugeben und gut einarbeiten",null,null,null,null,null,false],["Öl zugeben und bis zu voller Glutenentwicklung kneten",null,null,null,null,null,false],["20 Minuten Stockgare",null,null,null,null,null,false],["Zu 360 g Kugeln wirken",null,null,null,null,null,false],["Abgedeckt bei 4ºC 1 -2 Tage Stückgare",null,null,null,null,null,false]]]]],["teig-fuer-pizza-napoletana-modernistisch","gericht","Teig für Pizza Napoletana Modernistisch",null,null,null,4,null,null,["Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[["Vorverkleistertes Mehl",[["Wasser",120.0,0,null],["Mehl Tipo 00",30.0,0,null]],[]],["Teig",[["Wasser",380.0,0,null],["Trockenhefe",0.24,0,null],["Mehl Tipo 00",580.0,0,null],["Papain",0.15,0,null]],[]],["Zubereitung",[],[["Wasser und Mehl in einem kleinen Topf mischen und auf 65ºC erwärmen. Dann sofort abkühlen",null,null,null,null,null,false],["Wasser Hefe und vorverkleistertes Mehl vermengen. Mehl und Papain zufügen und vermischen. Salz zugeben und gut kneten. Fenstertest.",null,null,null,null,null,false],["In Wanne zugedeckt bei Raumtemperatur 20 - 24 h gehen lassen.",null,null,null,null,null,false],["Kugeln à 250 g verwirken.",null,null,null,null,null,false],["3 h Stückgare",null,null,null,null,null,false]]]]],["thai-gurkensalat","gericht","Thai Gurkensalat",null,null,null,4,null,null,["2 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","7 von 12 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Palmzucker",50.0,0,null],["Fischsauce (es gibt auch eine vegane Variante)",50.0,2,"50 ml (1 ml = 1 g)"],["Limettensaft",80.0,2,"80 ml (1 ml = 1 g)"],["Cherrytomaten",50.0,0,null],["Knoblauchzehe",null,0,"1 Knoblauchzehe"],["roter Peperoncino",null,0,"1/2 roter Peperoncino"],["Jasminreis",10.0,0,null],["Snack-Gurken, längs in feine Scheiben gehobelt",null,0,"10 Snack-Gurken, längs in feine Scheiben gehobelt"],["roter Peperoncino, in feine Ringe geschnitten",null,0,"1 roter Peperoncino, in feine Ringe geschnitten"],["Korianderkresse",null,0,null],["kleine essbare Blüten nach Wunsch",null,0,null],["Cherrytomaten, geviertelt",null,0,"6 Cherrytomaten, geviertelt"]],[["In einem Topf den Palmzucker mit der Fischsauce schmelzen und dann abkühlen lassen. Die restlichen Zutaten zugeben und das Ganze fein mixen.",null,null,null,null,null,false],["Ungekochten Jasminreis in einer Pfanne ohne Fett rösten, abkühlen lassen und in eine Pfeffermühle geben. Die Gurkenscheiben mit etwas Thai-Salsa marinieren und fächerförmig auf dem Teller anrichten. Thai-Salsa grosszügig darüber träufeln. Den Gurkensalat mit Peperoncini, Korianderkresse, Cherrytomaten und farbigen Blüten dekorieren. Den gerösteten Reis als Knusperelement über das Gericht mahlen.",null,null,null,null,null,false]]]]],["thom-yam-gung","komponente","Thom yam gung",null,null,null,null,null,null,["1 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","8 von 9 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["frische Garnelen",null,0,"10 frische Garnelen"],["Wasser",1000.0,2,"1 L (1 ml = 1 g)"],["grosse Prise Salz",null,0,"1 grosse Prise Salz"],["Fischsauce",null,0,"1 EL"],["Vogelaugenchilis",null,0,"3-7 Vogelaugenchilis"],["Stängel Zitronengras",null,0,"2 Stängel Zitronengras"],["Kaffirlimettenblätter",null,0,"3 Kaffirlimettenblätter"],["Limettensaft",null,0,"3 EL"],["Fischsauce, zum abschmecken",null,0,null]],[["Garnelen schälen und entdarmen. Köpfe und Schalen in einer Pfanne mit Wasser",null,null,null,null,null,false],["und Salz und Zitronengras zum Kochen bringen und ca. 10 Minuten köcheln",null,null,null,null,null,false],["lassen. Absieben und wieder zum Kochen bringen. Mit Fischsauce würzen. Chilis",null,null,null,null,null,false],["im Mörser zerdrücken und die Hälfte davon zur Suppe geben. Limettenblätter in",null,null,null,null,null,false],["der Hand zerdrücken und dazugeben.",null,null,null,null,null,false],["Die Garnelen mit den restlichen Chilis und dem Limettensaft in einer",null,null,null,null,null,false],["Servierschüssel marinieren. Die kochende Suppe darübergiessen und 5 Minuten",null,null,null,null,null,false],["ziehen lassen.",null,null,null,null,null,false]]]]],["tokatsu-sauce","komponente","Tokatsu Sauce",null,null,null,null,null,null,["26 von 26 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["g",null,0,"75 g"],["Apple juice",null,0,null],["g",null,0,"75 g"],["Worcestershire sauce",null,0,null],["g",null,0,"65 g"],["Tomato paste",null,0,null],["g",null,0,"40 g"],["Soy sauce",null,0,null],["g",null,0,"25 g"],["Dijon mustard",null,0,null],["g",null,0,"25 g"],["Light brown sugar",null,0,null],["g",null,0,"15 g"],["Lemon juice, fresh (from 1 lemon)",null,0,null],["g",null,0,"8 g"],["Distilled vinegar",null,0,null],["g",null,0,"1.5 g"],["Garlic p