select importer.rezepte('[["tonic","komponente","Tonic",null,null,null,null,null,null,["2 von 12 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[["Cinarinden Sirup",[["Chinarinde",20.0,0,null],["Wasser",750.0,0,null],["Zucker",750.0,0,null]],[]],["Limetten Sirup",[["Zucker",400.0,0,null],["Wasser",400.0,0,null],["Limetten Zest",null,0,"10 Limetten Zest"]],[]],["Tonic Base",[["Chinarinden Sirup",300.0,0,null],["Lime Sirup",200.0,0,null],["h klarer Grapefruit Saft",null,0,"150 h klarer Grapefruit Saft"]],[]],["Tonic",[["Tonic Base",280.0,0,null],["Wasser",565.0,0,null],["Limettensaft",150.0,0,null]],[]]]],["tonkabohneneis","komponente","Tonkabohneneis",null,"Pacojet",null,null,null,null,["Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Sahne",90.0,0,null],["Milch",330.0,0,null],["Zucker",100.0,0,null],["Eigelb",100.0,0,null],["Tonkabohnen",3.6,0,null]],[]]]],["ube-cake","gericht","Ube Cake",null,null,"allrecipes.com",12,null,null,["16 von 16 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Portionsgrösse in Gramm fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["flour",null,0,"2 1/2 Cup"],["baking powder",null,0,"3 teaspoons"],["salt",null,0,"1 teaspoon"],["Ube",null,0,"1 cup"],["milk",null,0,"3/4 cup"],["vanilla extract",null,0,"1 teaspoon"],["egg yolks",null,0,"7 egg yolks"],["agarve",null,0,"1/2 cup"],["vegetable oil",null,0,"1/2 cup"],["egg whites",null,0,"7 egg whites"],["crem of tartar",null,0,"1 teaspoon"],["sugar",null,0,"1 cup"],["Red food coloring",null,0,null],["Blue food coloring",null,0,null]],[]],["Buttercream",[["condensed milk",null,0,"1 cup"],["butter",null,0,"1 cup"]],[]],["Zubereitung",[],[["Preheat the oven to 325 degrees F (165 degrees C). Line the bottom of three 9-inch round pans with parchment paper, but do not grease.",null,null,null,null,null,false],["Make the ube cake: Mix flour, baking powder, and salt together in a large bowl; set aside. Place grated ube in a large bowl. Combine 3/4 cup milk and 1 teaspoon vanilla; gradually blend into ube until smooth. Blend in egg yolks, corn syrup, and oil. Beat in flour mixture until smooth; set aside.",null,null,null,null,null,false],["Combine egg whites and cream of tartar in a large bowl; beat with an electric mixer until foamy. Gradually add sugar, then red and blue food coloring, continuing to beat until stiff peaks form. Fold 1/3 of the whites into batter, then quickly fold in remaining whites until no streaks remain. Pour batter into prepared pans.",null,null,null,null,null,false],["Bake in the preheated oven until a toothpick inserted into the center comes out clean, about 30 to 35 minutes. Invert pans on a wire rack and let cool upside down. When cool, run a knife around the edges to loosen cake from the pans. Spread coconut preserves onto the cooled cake layers; stack layers on a cake stand or serving plate.",null,null,null,null,null,false],["Make the buttercream: Combine evaporated milk and 3/4 cup sugar; set aside. Combine butter and sugar in a large bowl; beat with an electric mixer until smooth and creamy. Beat in food coloring, one drop at a time, until the desired tint is achieved. Frost top and sides of cake with buttercream.",null,null,null,null,null,false]]]]],["umami-bomb-grilling-powder","komponente","Umami Bomb Grilling Powder",null,null,null,null,null,null,["Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Cremini mushrooms",450.0,0,null],["Nutritional yeast",2.0,0,null],["Garlic, cloves",15.0,0,null],["Shallot",60.0,0,null],["Serrano pepper",15.0,0,null],["Chives",20.0,0,null],["Himalayan salt",15.0,0,null],["Worcestershire sauce",20.0,0,null],["Canola oil",15.0,0,null]],[["This recipe requires the roasting function of an oven to help build flavor and the drying function of a dehydrator to remove moisture.",null,null,null,null,null,false],["Some ovens feature both of these functions and some do not. If you do not have a multifunctional oven—the next best thing is to lightly roast the vegetables and then transfer them into a dehydrator.",null,null,null,null,null,false],["If you do not have a dehydrator—when you reach Step 7, drop the oven temperature to 200 °F / 93 °C and cook until completely dry. Remember to stir a few times during the baking process. This could take several hours.",null,null,null,null,null,false],["Brush away any dirt from the mushrooms.",null,null,null,null,null,false],["Slice the mushrooms into pieces about one-quarter of an inch thick. This thickness will help the mushrooms dry out at a quicker rate.",null,null,null,null,null,false],["Toss the mushrooms into a mixing bowl.",null,null,null,null,null,false],["Peel the shallots and garlic cloves. Remove the seeds from the peppers. Slice them all lengthwise into pieces about one-quarter of an inch wide. Slice the chives into three-inch long pieces.",null,null,null,null,null,false],["Add the aromatic vegetables along with the Worcestershire sauce, canola oil, and the nutritional yeast to the bowl of sliced mushrooms. Toss to coat and spread the mixture out evenly onto a parchment-lined sheet pan.",null,null,null,null,null,false],["Preheat the oven to 400 °F / 204 °C and position the rack in the middle.",null,null,null,null,null,false],["Place the sheet pan into the preheated oven and lightly roast the vegetables at 400 °F / 204 °C for five minutes.",null,null,null,null,null,false],["This initial roast will start the Maillard reaction and deepen the flavor of the final powder.",null,null,null,null,null,false],["If you do not have a fan in your oven to use as a dehydrator, then roast the vegetables for five additional minutes before transferring the mixture into a stand-alone dehydrator.",null,null,null,null,null,false],["For an oven with a fan or dehydrator setting: Following the five-minute roast, drop the oven temperature to 140 °F / 60 °C and set the fan on a high setting or dehydrate mode for 12 hours or until fully dry.",null,null,null,null,null,false],["If you are using a stand-alone dehydrator: Following the 10-minute roast in the oven, set the temperature to 140 °F / 60 °C and dehydrate for 12 hours or until fully dry. The vegetables will be firm to the touch and should snap and not bend when they are ready.",null,null,null,null,null,false],["If you do not have an oven with a fan or a stand-alone dehydrator: Following the five-minute roast, drop the oven temperature to 200 °F / 93 °C and cook the mushroom mixture until completely dry. Remember to stir a few times during the baking process. This could take several hours.",null,null,null,null,null,false],["The vegetable mixture must be fully dry to grind into a powder.",null,null,null,null,null,false],["Remove the vegetable mixture from the dehydrator. The vegetables should be firm, dry, and look wrinkled. Allow the mixture to cool to room temperature. Grind the mixture into a powder using a spice grinder and then add the salt. We use Himalayan salt because it contains other minerals, like sulfur, that amplify the umami experience on the tongue.If Himalayan salt is unavailable then any sea salt or kosher salt will work as a replacement.",null,null,null,null,null,false],["Store the umami powder in an airtight jar to keep it from attracting moisture. It will last indefinitely.",null,null,null,null,null,false],["You can use this mixture as a grilling seasoning before and after cooking for any meats or vegetables, or keep it handy when you need to drop a mushroom bomb on anything that needs a boost of flavor!",null,null,null,null,null,false]]]]],["umami-mushroom-ketchup","komponente","Umami Mushroom Ketchup",null,null,null,null,null,null,["4 von 13 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Portobello mushrooms, about 4-5 large caps and stems",500.0,0,null],["Onion(s), about 1 large",250.0,0,null],["-",null,0,null],["Black pepper, as needed",null,0,null],["-",null,0,null],["Canola oil, as needed",null,0,null],["Salt",12.0,0,null],["Apple cider vinegar",300.0,0,null],["Brown sugar",150.0,0,null],["Blackstrap molasses",50.0,0,null],["Allspice",0.2,0,null],["Cloves, about two whole cloves",0.1,0,null],["Xanthan gum, optional",1.0,0,null]],[]]]],["vanilleeiscreme","komponente","Vanilleeiscreme",null,"Pacojet",null,null,null,null,["Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Sahne",90.0,0,null],["Milch",330.0,0,null],["Zucker",120.0,0,null],["Eigelb",100.0,0,null],["Vanilleschote",3.0,0,null]],[["(1) Die Vanilleschote aufschneiden und auskratzen. Sahne und Milch aufkochen, Eigelb und Zucker vermengen und einrühren, Vanille Mark und Schote beigeben, auf 82 °C erhitzen. Die Schote entfernen und die Masse in einen Pacossier®-Becher füllen.",null,null,null,null,null,false],["(2) Mit Deckel schliessen und beschriften. Bei −20 °C für mindestens 24 h tiefgefrieren.",null,null,null,null,null,false],["(3) Bei Bedarf 1-mal Pacossieren®.",null,null,null,null,null,false]]]]],["vormittags-landbrot","komponente","Vormittags Landbrot",null,"Brot",null,null,null,null,["Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Weissmehl (Weizenmehl Type 550)",300.0,0,null],["Roggenmehl hell oder dunkel",120.0,0,null],["Weizen Vollkornmehl",80.0,0,null],["Sauerteig",80.0,0,null],["Salz",11.0,0,null],["Frischhefe",6.0,0,null],["Backmalz, aktiv",3.0,0,null],["Wasser",200.0,0,null],["Vollmilch",160.0,0,null]],[["Alle Zutaten in die Küchenmaschine geben und auf kleiner Stufe 2-3 Min ankneten.",null,null,null,null,null,false],["Danach die Knetgeschwindigkeit erhöhen und den Teig total ca. 10-15 Min. schonend kneten.",null,null,null,null,null,false],["Anschliessend den Teig in ein leicht gefettetes Becken legen, mit einem Teigtuch (Gärfolie) zudecken und 2,5-3 Std. bei Raumtemperatur gären lassen.",null,null,null,null,null,false],["In der Zwischenzeit den Teig 1-2 Mal dehnen und falten:",null,null,null,null,null,false],["Hierzu ziehst Du den Teig an einer Seite leicht hoch und legst den Teig an den gegenüberliegenden Beckenrand. Dies geht am besten, wenn Du Deine Hände vorgängig in etwas Wasser tunkst.",null,null,null,null,null,false],["Diesen Vorgang von allen vier Seiten wiederholen, den Teig wieder zudecken und die restliche Zeit gären lassen.",null,null,null,null,null,false],["Formen",null,null,null,null,null,false],["Nach der Gärzeit den Teig auf eine bemehlte Arbeitsfläche geben und schonend 1-2 Mal über die bemehlte Arbeitsfläche schleifen, um eine glatte Oberfläche zu bekommen.",null,null,null,null,null,false],["Dabei den Teig mit den Fingern von einer Seite zur Mitte ziehen und leicht andrücken.",null,null,null,null,null,false],["Diesen Vorgang reihum wiederholen und den Teig immer wieder in die Mitte falten.",null,null,null,null,null,false],["Das Teigstück vom Mehl nehmen, umdrehen (glatte Seite liegt nun oben) und die Hände vasenförmig darum legen. Dann den Teigling mit leichtem Druck auf der Tischplatte drehen, bis er unten geschlossen ist.",null,null,null,null,null,false],["Es ist von Vorteil, wenn sich dabei im Teigstück etwas Spannung aufbaut. Tipp: Damit sich die Teigkugel am unteren Ende gut verschiesst, sollte bei diesem Arbeitsschritt kein bis nur ganz wenig Mehl verwendet werden.",null,null,null,null,null,false],["Den Teigling mit dem Verschluss nach oben in einen runden, bemehlten Gärkorb legen, mit einer Gärfolie zudecken und für 30-40 Min. bei Raumtemperatur gären lassen.",null,null,null,null,null,false],["In der Zwischenzeit den Backofen mit einem Brotbackstein oder einer Backplatte in der unteren Ofenhälfte auf 230 Grad Ober-/Unterhitze vorheizen.",null,null,null,null,null,false],["Backen",null,null,null,null,null,false],["Nach der Stückgare den Teigling auf eine Brotschaufel stürzen (Verschluss ist nun unten) und mit einem scharfen Messer (oder Klinge) mit senkrechter Klingenführung die Oberflache rautenförmig einschneiden.",null,null,null,null,null,false],["Danach den Teigling von der Brotschaufel direkt auf das heisse Blech im Ofen abschieben.",null,null,null,null,null,false],["Den Backofen bedampfen, die Temperatur auf 220 Grad reduzieren und das Brot für 20 Min. backen.",null,null,null,null,null,false],["Nach 20 Min. die Ofentür kurz öffnen, damit der Dampf entweichen kann und dann das Brot noch weitere 30-35 Min. fertig backen.",null,null,null,null,null,false]]]]],["wurst-kaese-salat","komponente","Wurst-Käse-Salat",null,"GM Rezepte","«Schäfli» Wigoltingen",null,null,null,["7 von 8 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Schrofen-Klöpfer/Cervelat",null,0,"4 Schrofen-Klöpfer/Cervelat"],["Käse z.B. «Der freche Maxx», mit Röstiraffel gehobelt",200.0,0,null],["Essiggurken in Scheiben",null,0,"4 Essiggurken in Scheiben"],["Chinakohl, in feine Streifen geschnitten",null,0,"1/4 Chinakohl, in feine Streifen geschnitten"],["Frühlingszwiebeln, in Röllchen geschnitten",null,0,"4 Frühlingszwiebeln, in Röllchen geschnitten"],["Schnittlauchröllchen",null,0,"4 EL"],["Petersilienstreifen",null,0,"4 EL"],["Süssmais",null,0,"4 EL"]],[["Die Würste der Länge nach halbieren und in dünne Scheiben schneiden.",null,null,null,null,null,false],["Alle anderen Zutaten mit der Salatsauce in einer Schüssel mischen, mit Schnittlauchröllchen garnieren und servieren.",null,null,null,null,null,false]]]]],["wurzelbrot","komponente","Wurzelbrot",null,"Brot",null,null,null,null,["Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Weissmehl",525.0,0,null],["Roggenmehl",60.0,0,null],["Wasser",400.0,0,null],["Salz",15.0,0,null],["Frischhefe",0.4,0,null]],[]]]],["xo-sauce-von-tohru","komponente","XO-Sauce von Tohru",null,null,null,null,null,null,["2 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","4 von 11 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["getrocknete Jakobsmuscheln (siehe Text)",50.0,0,null],["getrocknete Shrimps (Asienladen, grösser ist meist besser)",50.0,0,null],["Parma- oder Serranoschinken (Original: Yunnan-Schinken)",100.0,0,null],["neutrales Öl",250.0,2,"250 ml (1 ml = 1 g)"],["junge Knoblauchknollen für etwa 75 g geschälte Knoblauchzehen",null,0,"2 junge Knoblauchknollen für etwa 75 g geschälte Knoblauchzehen"],["Ingwerwurzel",100.0,0,null],["Thai-Schalotten",100.0,0,null],["Salz",null,0,"1/2 TL"],["Zucker",null,0,"1 EL"],["rote Chiliflocken (getrocknete Jalapenos sind zum Beispiel gut, schön aromatisch nicht höllisch scharf)",null,0,"1 EL"],["ShaoXing-Wein (Asienladen)",100.0,2,"100 ml (1 ml = 1 g)"]],[["Jakobsmuscheln und Shrimps in einer Schüssel mit kaltem Wasser knapp bedecken, über Nacht einweichen. Abgiessen.",null,null,null,null,null,false],["Knoblauchzehen, Ingwer und Schalotten schälen und in Scheiben schneiden.Jakobsmuscheln, Shrimps, Knoblauch, Ingwer und Schalotten fein hacken - zum Beispiel im Universalzerkleinerer. Schinken ebenfalls fein hacken, aber noch nicht mischen.",null,null,null,null,null,false],["Etwa die Hälfte vom Öl erhitzen, den Schinken darin bei schwacher bis mittlerer Hitze etwa 4 Minuten lang braun braten. Die Jakobsmuschel-Mischung, Salz und Zucker zugeben. Etwa 60 Min. bei ganz, ganz sanfter Hitze schmoren, dabei oft umrühren. Chiliflocken nur noch kurz unterrühren und rösten, mit ShaoXing-Wein ablöschen, 15 Min. einkochen und dann vom Herd nehmen.",null,null,null,null,null,false],["Restliches Öl zugeben und kühl aufbewahren, hält sich Monate lang und passt zu fast allem. Zum Beispiel von süsslichen Meeresfrüchten wie Tintenfisch, Jakobsmuschel oder Krustentieren über alle Arten von puristisch gegartem Gemüse bis zu gebratenem Geflügel oder Schweinefleisch. Auch asiatische Reis- und Nudelgerichte oder Stirfries profitieren von der Sauce.",null,null,null,null,null,false]]]]],["yuzu-sorbet","komponente","Yuzu Sorbet",null,"Pacojet",null,null,null,null,["Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["Wasser",500.0,0,null],["Glukosesirup",60.0,0,null],["Zucker",110.0,0,null],["Yuzusaft",60.0,0,null],["Stab2000",2.9,0,null]],[]]]],["zopf","komponente","Zopf",null,"Brot",null,null,null,null,["3 von 11 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[["Vorteig",[["Weissmehl",100.0,0,null],["Sauerteig",10.0,0,null],["Wasser",70.0,0,null]],[]],["Teig",[["Vorteig",null,0,null],["Milch",310.0,0,null],["Ei",null,0,"1 Ei"],["Zopfmehl",600.0,0,null],["Butter",110.0,0,null],["Salz",15.0,0,null],["Hefe",12.0,0,null]],[]],["zum Bestreichen",[["Ei verquirlt",null,0,"1 Ei verquirlt"]],[]],["Zubereitung",[],[["Vorteig",null,null,null,null,null,false],["Alles zusammen von Hand zu einem Teig verkneten. Danach den Vorteig mit einem Teigtuch (Gärfolie) zudecken und für 12-18 Std. bei Raumtemperatur gären lassen.",null,null,null,null,null,false],["Hauptteig",null,null,null,null,null,false],["Alle Zutaten in die Küchenmaschine geben und auf kleiner Stufe beginnen zu kneten. Nach ca. 2-3 Min. die Knetgeschwindigkeit erhöhen und den Teig bei mittlerer Geschwindigkeit 10-12 Min. weiter kneten. Danach mit der “Fensterprobe” (siehe unter “gut zu wissen”) den Teig prüfen. Wenn der Teig noch klebrig ist und reisst, den Teig weiter kneten, bis er die Fensterprobe besteht.",null,null,null,null,null,false],["Den Teig in ein leicht gefettetes Becken legen, mit einem Teigtuch (Gärfolie) zudecken und für 60 Min. bei Raumtemperatur aufgehen lassen.",null,null,null,null,null,false],["Formen",null,null,null,null,null,false],["Den Teig in 4 Stücke zu ca, 320 g einteilen und jedes Teigstück länglich zu je einem Strang formen. Dabei die Stränge zuerst nur leicht vorrollen, entspannen lassen und erst danach in die richtige Länge von ca. 60-70 cm rollen.",null,null,null,null,null,false],["Am besten rollst Du zuerst alle Teigstücke vor und beginnst dann wieder mit dem ersten Strang, um die Stränge nacheinander in die richtige Länge zu rollen.",null,null,null,null,null,false],["2-Strang-Zopf",null,null,null,null,null,false],["Zwei Stränge kreuzweise übereinander legen. Danach das obere Ende des untersten Stranges über den oberen Strang nach unten legen und das untere Ende des untersten Stranges über den oberen Strang nach oben legen.",null,null,null,null,null,false],["Anschliessend das rechte Ende des waagrecht liegenden Stranges nach links und das linke Ende nach rechts legen. Das nun links oben liegende Ende vom oben liegenden Strang nach links, zwischen die unten liegenden Stränge legen.",null,null,null,null,null,false],["Dann das Ende des rechts unten liegenden Stranges, über die beiden Stränge auf der linken Seite legen. So weiterfahren, bis der ganze Zopf geflochten ist. Das heisst, immer mit den oben liegenden Strängen weiter flechten. Am Schluss die Enden gut zusammendrücken.",null,null,null,null,null,false],["Tipp: Beim Flechten der Zöpfe darauf achten, dass diese schön locker und gleichmässig geflochten und die Stränge nicht verzogen werden.",null,null,null,null,null,false],["Fertigstellung Butterzopf",null,null,null,null,null,false],["Die beiden Zöpfe mit einem verquirlten Ei bestreichen und für 40-50 Min. bei Raumtemperatur aufgehen lassen. In der Zwischenzeit den Backofen mit einem leeren Blech in der unteren Ofenhälfte auf 210 Grad Umluft vorheizen.",null,null,null,null,null,false],["Variante I",null,null,null,null,null,false],["Die Zöpfe zugedeckt über Nacht in den Kühlschrank stellen.",null,null,null,null,null,false],["Variante II",null,null,null,null,null,false],["Die Zöpfe flechten und noch vor der Gare in den Tiefkühler geben. Zum Auftauen die Zöpfe über Nacht im Kühlschrank In den Kühlschrank geben. Am nächsten Morgen die Zöpfe mit Ei bestreichen und bei Raumtemperatur 40-50 Min. aufgehen lassen.",null,null,null,null,null,false],["Backen",null,null,null,null,null,false],["Bei allen obenerwähnten Varianten: Vor dem Backen die Zöpfe nochmals mit einem verquirlten Ei bestreichen und dann direkt mit dem Blech in den vorgeheizten Ofen schieben. Nach ca. 2 Minuten – wenn die Eierstreiche etwas angetrocknet ist - zirka 1-2 dl Wasser auf das zweite Blech giessen und die Ofentür sofort schliessen. Die Zöpfe für 20 Minuten bei 210 Grad Umluft backen.",null,null,null,null,null,false],["Nach 20 Minuten das Blech mit dem Wasser aus dem Ofen nehmen, die Ofentemperatur auf 190 Grad Ober-Unterhitze umstellen und die Zöpfe für weitere 10-15 Minuten knusprig ausbacken.",null,null,null,null,null,false],["Nach dem Backen die Zöpfe auf einem Gitter gut auskühlen lassen.",null,null,null,null,null,false]]]]],["gai-pet-metmamuang","komponente","gai pet metmamuang",null,null,null,null,null,null,["15 von 15 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["g",null,0,"600 g"],["Hühnerbrust",null,0,null],["rote und gelbe Peperoni",null,0,"1 rote und gelbe Peperoni"],["6",null,0,"6"],["Frühlingszwiebeln",null,0,null],["Schalotten",null,0,"2 - 3 Schalotten"],["Knoblauchzehen",null,0,"3 - 4 Knoblauchzehen"],["Erdnussöl",null,0,null],["EL",null,0,"4 - 5 EL"],["Cashewnüsse",null,0,null],["Austernsauce",null,0,"1 EL"],["helle Sojasauce",null,0,"1 EL"],["wenig Fond",null,0,null],["Fischsauce",null,0,null],["getrockneter grosser Chili",null,0,"1 getrockneter grosser Chili"]],[["Fleisch, Peperoni und Frühlingszwiebeln in mundgerechte Stücke schneiden.",null,null,null,null,null,false],["Die Schalotten fein schneiden, den Knoblauch hacken und zusammen in wenig Öl",null,null,null,null,null,false],["goldbraun braten. Die Nüsse ohne Fett in einer Bratpfanne langsam rösten. Das",null,null,null,null,null,false],["Fleisch portionenweise braten. Das Gemüse kurz und scharf anbraten, Das",null,null,null,null,null,false],["gebratene Fleisch, die Nüsse, den Chili und die Zwiebel-Knoblauch-Mischung",null,null,null,null,null,false],["dazugeben. Mit Austernsauce, Soja und wenig Fischsauce würzen. Bei Bedarf mit",null,null,null,null,null,false],["wenig Fond verlängern. Abschmecken und sofort servieren.",null,null,null,null,null,false]]]]],["gai-pet-metmamuang-2","komponente","gai pet metmamuang",null,"Chicken, Thai",null,null,null,null,["10 von 11 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Hühnerbrust",600.0,0,null],["rote und gelbe Peperoni",null,0,"1 rote und gelbe Peperoni"],["Frühlingszwiebeln",null,0,"6 Frühlingszwiebeln"],["Schalotten",null,0,"2 - 3 Schalotten"],["Knoblauchzehen",null,0,"3 - 4 Knoblauchzehen"],["Erdnussöl",null,0,null],["Cashewnüsse",null,0,"4 - 5 EL"],["Austernsauce",null,0,"1 EL"],["helle Sojasauce wenig Fond",null,0,"1 EL"],["Fischsauce",null,0,null],["getrockneter grosser Chili",null,0,"1 getrockneter grosser Chili"]],[["Fleisch, Peperoni und Frühlingszwiebeln in mundgerechte Stücke schneiden.",null,null,null,null,null,false],["Die Schalotten fein schneiden, den Knoblauch hacken und zusammen in wenig Öl goldbraun braten. Die Nüsse ohne Fett in einer Bratpfanne langsam rösten. Das Fleisch portionenweise braten. Das Gemüse kurz und scharf anbraten, Das gebratene Fleisch, die Nüsse, den Chili und die Zwiebel-Knoblauch-Mischung dazugeben. Mit Austernsauce, Soja und wenig Fischsauce würzen. Bei Bedarf mit wenig Fond verlängern. Abschmecken und sofort servieren.",null,null,null,null,null,false]]]]],["geng-panaeng-gung","komponente","geng panaeng gung",null,null,null,null,null,null,["2 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","11 von 14 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Curry-Paste",null,0,"1-2 EL"],["Erdnussöl",null,0,null],["Kokosnussmilch",400.0,2,"4 dl (1 ml = 1 g)"],["Fond",200.0,2,"2 dl (1 ml = 1 g)"],["3",null,0,"3"],["Limettenblätter, in feine Streifen schneiden",null,0,null],["EL",null,0,"1 EL"],["Erdnüsse ungesalzen, fein mahlen",null,0,null],["2 - 3",null,0,"2 - 3"],["Frühlingszwiebeln, fein schneiden",null,0,null],["Schalotten, fein schneiden",null,0,"1 - 2 Schalotten, fein schneiden"],["Fischsauce, Zucker",null,0,null],["Chilis, Thai-Basilikum",null,0,null],["Crevetten",400.0,0,null]],[["Curry in wenig Öl anbraten, mit Kokosmilch und Fond ablöschen. Limettenblätter,",null,null,null,null,null,false],["Erdnüsse, Schalotten und Frühlingszwiebeln dazugeben und alles leicht köcheln",null,null,null,null,null,false],["lassen bis der Curry schön sämig wird. Bei Bedarf mit Kokosmilch oder Fond",null,null,null,null,null,false],["verdünnen. Mit Zucker und Fischsauce abschmecken. Crevetten nur 3 - 4",null,null,null,null,null,false],["Minuten im Curry garen und servieren. Mit Chilistreifen und Basilikum garnieren.",null,null,null,null,null,false],["Variationen: frische grüne Pfefferkörner mitkochen, oder mit Litschi garnieren.",null,null,null,null,null,false]]]]],["geng-panaeng-gung-2","komponente","geng panaeng gung",null,"Fish, Thai",null,null,null,null,["2 Menge(n) in ml, dl oder l als Gramm übernommen (1 ml = 1 g): bitte prüfen.","8 von 11 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Curry-Paste",null,0,"1-2 EL"],["Erdnussöl",null,0,null],["Kokosnussmilch",400.0,2,"4 dl (1 ml = 1 g)"],["Fond",200.0,2,"2 dl (1 ml = 1 g)"],["Limettenblätter, in feine Streifen schneiden",null,0,"3 Limettenblätter, in feine Streifen schneiden"],["Erdnüsse ungesalzen, fein mahlen",null,0,"1 EL"],["Frühlingszwiebeln, fein schneiden",null,0,"2 - 3 Frühlingszwiebeln, fein schneiden"],["Schalotten, fein schneiden",null,0,"1 - 2 Schalotten, fein schneiden"],["Fischsauce, Zucker",null,0,null],["Chilis, Thai-Basilikum",null,0,null],["Crevetten",400.0,0,null]],[["Curry in wenig Öl anbraten, mit Kokosmilch und Fond ablöschen. Limettenblätter, Erdnüsse, Schalotten und Frühlingszwiebeln dazugeben und alles leicht köcheln lassen bis der Curry schön sämig wird. Bei Bedarf mit Kokosmilch oder Fond verdünnen. Mit Zucker und Fischsauce abschmecken. Crevetten nur 3 - 4",null,null,null,null,null,false],["Minuten im Curry garen und servieren. Mit Chilistreifen und Basilikum garnieren. Variationen: frische grüne Pfefferkörner mitkochen, oder mit Litschi garnieren.",null,null,null,null,null,false]]]]],["hor-mok-pla","komponente","hor mok pla",null,null,null,null,null,null,["12 von 14 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Fischfilet, z.B. Pangasius, Kabeljau, Weissling",200.0,0,null],["Salz",null,0,"1 Prise"],["wenig Limettensaft",null,0,null],["Fischsauce",null,0,"2 EL"],["Zucker",null,0,"1 Prise"],["Kokosmilch",125.0,0,null],["Ei",null,0,"1 Ei"],["6",null,0,"6"],["Kaffirlimettenblätter",null,0,null],["Bananenblätter",null,0,null],["Thai-Basilikum",null,0,null],["wenig dicke Kokoscreme",null,0,null],["rote Chili, in feine Streifen",null,0,"1 rote Chili, in feine Streifen"],["Currypaste",null,0,"1-2 EL"]],[["Filets mit gesalzenem, gesäuertem (einige Spritzer Limettensaft) Wasser waschen.",null,null,null,null,null,false],["Gut abtropfen, in Streifen scheiden und in eine Schüssel geben. Den Fisch mit",null,null,null,null,null,false],["Zucker und Fischsauce würzen. Langsam die Kokosmilch einrühren. Die",null,null,null,null,null,false],["Konsistenz sollte wie eine Mayonnaise sein. Die Curypaste darunter ziehen und",null,null,null,null,null,false],["abschmecken. Es sollte salzig und süss sein und nach Kokoscreme duften. Das Ei",null,null,null,null,null,false],["und die Limettenblätter dazugeben und einige Minuten ziehen lassen. Aus den",null,null,null,null,null,false],["Bananenblätter ca. 12 cm grosse Kreise ausschneiden. Jeweils 2 Kreise mit der",null,null,null,null,null,false],["glänzenden Seite zusammenlegen und daraus kleine Körbe formen. Den Boden",null,null,null,null,null,false],["mit Basilikum auslegen und den Curry hineingeben. 15 bis 30 Minuten dämpfen.",null,null,null,null,null,false],["Mit der Kokoscreme und Chilistreifen garnieren.",null,null,null,null,null,false]]]]],["tort-man-pla-fischplaetzchen","komponente","tort man pla Fischplätzchen",null,"Fish, Thai",null,null,null,null,["7 von 8 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Fischfilet",300.0,0,null],["rote Currypaste",null,0,"1-2 EL"],["Ei",null,0,"1 Ei"],["Fischsauce",null,0,"3 EL"],["Zucker",null,0,"1 TL"],["Kaffirlimettenblätter, fein geschnitten",null,0,"5 Kaffirlimettenblätter, fein geschnitten"],["Schlangenbohnen, fein geschnitten",null,0,"2 EL"],["Öl zum frittieren",null,0,null]],[["Fisch in Salzwasser waschen. Fisch, Currypaste und Ei im Mixer zu einer Farce verarbeiten. Mit Zucker und Fischsauce abschmecken. Farce in einer grossen Schüssel zu einer Kugel formen und diese so lange in die Schüssel werfen, bis die Masse fester und klebriger wird. Dadurch kommt Luft in die Farce, und die Plätzchen gehen beim frittieren auf. Am Schluss Kaffirlimettenblätter und Bohnen unter die Masse arbeiten. Mit einem Esslöffel Portionen abstechen und zu Plätzchen formen, dann in Öl bei mittlerer Hitze frittieren.",null,null,null,null,null,false]]]]],["wagyu-steak","komponente","“Wagyu” Steak",null,null,null,null,null,null,["2 von 5 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["Total weight ground brisket",3200.0,0,null],["Knox gelatin, 1.5% of final grind weigh",48.0,0,null],["Salt, kosher, 1% of final grind weight",32.0,0,null],["-",null,0,null],["Black pepper, coarsely ground, as needed",null,0,null]],[["First separate your brisket into lean meat and fat so that you will be able to accurately scale out your lean-to-fat ratio later.",null,null,null,null,null,false],["After breaking down five briskets for our trials, we had an average lean-to-fat ratio of about 65:35, so you might have a little bit of trim left over to get to our recommended lean-to-fat ratio of 70:30 for this ultimate chop steak. Just pack up the leftover trim and freeze it for your next batch. Slice the meat into half-inch to three-quarter-inch cubes and get your meat as cold as possible—not fully frozen but almost there.",null,null,null,null,null,false],["If you don’t want to grind up a whole brisket, you can get a chunk of whatever size you want from your local butcher, but you will want the point cut to make sure you have enough fat to work with.",null,null,null,null,null,false],["For this chop steak, we go with a smaller grind size of 3 mm. This helps get the sliceable texture we are looking for and keeps the final steak from eating like a plain old burger.",null,null,null,null,null,false],["For more on grinding your own meats, see our Ultimate Burger Patty Guide for Purists.",null,null,null,null,null,false],["After grinding, weigh your final grind amount since there is normally some loss in the grinding process. Adjust the ingredients above so that you have the accurate percentage weights for the gelatin and salt.",null,null,null,null,null,false],["Sprinkle in your salt and gelatin and give it all a good mix. Don’t worry about over-mixing the ground beef as it will need a little extra processing overall to emulsify and create the final texture we are looking for.",null,null,null,null,null,false],["This combination of salt and gelatin are also key to the final texture of the chop steak. The salt helps firm up and “ham” the ground beef, and the gelatin binds and moistens up the mix.",null,null,null,null,null,false],["Portion the chop meat mix into 400 g portions. We want a solid size portion here so that we can get a full 1½ inches in thickness. This will allow you to replicate the nice, rosy, edge-to-edge look that you would get with a steak.",null,null,null,null,null,false],["Using your hands, squeeze and cream each portion 10 times. Then form a patty in any shape that you like and make sure that your top and bottom are nice and flat so that you will have a good even contact with your cooking surface. The dimensions of our steak were 1½ inches thick by 3½ wide by 5½ inches long.",null,null,null,null,null,false],["Once shaped, place the steaks in the refrigerator to set overnight. The gelatin will hydrate and the patty will get firm.",null,null,null,null,null,false],["After they rest overnight, freeze any portions you don’t plan on cooking within the next couple of days.",null,null,null,null,null,false],["NOTE: During our trials, we found that if we cooked the steaks immediately, the patties would stick like crazy to the grill, and we didn’t achieve the same juicy texture without giving the gelatin time to fully hydrate and the salt to bind the myosin in the meat.",null,null,null,null,null,false],["A note on temperature: 133 °F / 56 °C will result in our favorite doneness—rosy in color and very juicy. If you like your chop steaks very rare, opt for 126 °F / 52 °C. If you like your chop steaks more done, with just a hint of pink, you can go as high as 158 °F / 70 °C.",null,null,null,null,null,false],["Place your chop steaks into a ziplock-style bag, making sure they don’t overlap. You can easily fit two in a gallon-sized bag. Do not vacuum seal the patties—you don’t want to smash them.",null,null,null,null,null,false],["No need to add any butter or oil to the bags (unless you want to) or weight them down—these puppies will sink!",null,null,null,null,null,false],["Place the chop steaks in your sous vide bath and cook for 90 minutes at your chosen temperature. They can cook up to two hours without changing the texture of the steak.",null,null,null,null,null,false],["Once the chop steaks are done cooking, pull them out of the water and set them on the counter to rest for 15 minutes in the bag. Don’t worry about leaving them out of the bath, they will quickly reheat on the grill.",null,null,null,null,null,false],["This short rest will give the fat and gelatin time to set back up and keep both from escaping out of the steak when you throw it on the hot grill—causing flame-ups and moisture loss in the steaks.",null,null,null,null,null,false],["The key here is high heat and a well-seasoned grill.",null,null,null,null,null,false],["We know a lot of people have gas grills, but most just don’t hold a hot enough heat for this method. So if you can’t use a charcoal grill or don’t want to hack a chimney, just cook inside on your stovetop in a cast iron pan or under the broiler on max heat. It will get smoky, BUT YOU NEED MAXIMUM HEAT!",null,null,null,null,null,false],["The next best thing is a nonstick pan.",null,null,null,null,null,false],["After they have rested, remove the steaks from the bags, dry off the excess juices, and season with cracked black pepper.",null,null,null,null,null,false],["These are already cooked to the perfect doneness, so all you should worry about is getting the crust just the way you want it.",null,null,null,null,null,false],["If your grill is hot enough it should only take about one to two minutes on each side.",null,null,null,null,null,false]]]]],["chiu-chow-chili-oil-chili-crack","komponente","🌶️ Chiu Chow Chili Oil (Chili Crack)",null,null,null,null,null,null,["1 von 13 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zubereitung fehlt im Original."],[],[[null,[["heads of garlic or about 100g dried garlic granules",null,0,"2 heads of garlic or about 100g dried garlic granules"],["shallots",250.0,0,null],["ginger",20.0,0,null],["fresh chilies of choice",150.0,0,null],["dried chili flakes",30.0,0,null],["(smoked) salt",15.0,0,null],["cooking oil",350.0,0,null],["msg",5.0,0,null],["paprika powder",15.0,0,null],["toasted sesame seeds (optional)",25.0,0,null],["toasted sesame oil",15.0,0,null],["sugar",25.0,0,null],["Chinese dark vinegar",15.0,0,null]],[]]]],["morkovcha-korean-carrots","komponente","🥕 Morkovcha (Korean Carrots)",null,null,null,null,null,null,["11 von 14 Zutaten ohne Grammangabe (EL, TL, Stück, nach Geschmack): Originalangabe steht in der Notiz, Menge in Gramm fehlt.","Basiszutat für die Skalierung ist nicht festgelegt.","Ergibt-Menge pro Charge fehlt.","Zeiten und Geräte pro Schritt fehlen."],[],[[null,[["carrots (julienned, ~550g usable)",1000.0,0,null],["g salt (2%) for curing",null,0,"11–12g salt (2%) for curing"],["neutral oil",60.0,0,null],["white onion (finely sliced)",null,0,"½ white onion (finely sliced)"],["gochugaru",null,0,"3 tsp"],["rice vinegar",70.0,0,null],["sugar",null,0,"2 tsp"],["salt",null,0,"1 tsp"],["white pepper",null,0,"¼ tsp"],["pinch MSG",null,0,null],["cloves garlic (finely minced)",null,0,"3 cloves garlic (finely minced)"],["toasted cumin seeds",null,0,"½ tsp"],["toasted sesame seeds",null,0,"2 tsp"],["sesam",null,0,"2 tsp"]],[["1. Toss carrots with salt, rest 15–30 min until softened. Wrap in a kitchen towel and squeeze firmly to remove as much liquid as possible.",null,null,null,null,null,false],["2. Heat oil, fry onion until golden. Remove from heat, stir in gochugaru, infuse 2–3 min.",null,null,null,null,null,false],["3. Strain hot oil over carrots. Add all remaining ingredients and mix thoroughly.",null,null,null,null,null,false],["4. Chill at least 2h, best overnight (even better day 2).",null,null,null,null,null,false]]]]]]'::jsonb);
-- Notizen und Beschreibung nach «besonderes», Ertragsangabe als Text nach «chargengroesse»
update public.rezept r set besonderes = coalesce(r.besonderes, x.v->>1), chargengroesse = coalesce(r.chargengroesse, x.v->>2)
from jsonb_array_elements('[["4er-weizenlaib","8 - 16 Std. Gärdauer Vorteig\n3 - 4 Std. Stockgare\n60 - 90 Min. Stückgare30 Min. Aktivzeit\n40 - 50 Min. Aktivzeit\n230 - 210ºC",null],["baguettes","4 à 300 g\nHard Facts HauptteigTeigtemperatur 24-26°CTeigruhe 30 min+ 12-24hBacktemperatur 230-240°CBackdauer 18-22 min",null],["bianco","16-48 Std. Gärdauer Poolish\n8-12 Std. Gärdauer Vorteig\n60-90 Min. Stockgare\n30-50 Minuten Stückgare",null],["brauner-kalbsfond","Klein gehackte Knochen bewirken eine grössere aroma- und farbgebende Röstfläche; der daraus entstehende Fond hat eine schönere Farbe und einen intensiveren Geschmack. Für das Anrösten der Knochen im Umluftofen wird kein Fettstoff benötigt. Stiele von frischen Kräutern sowie Tomatenabschnitte können dem Fond individuell beigegeben werden.","5 Liter"],["calamansi-curd","Rezept von Raul @ Made Nice\nSuper zu Cheese cake",null],["couronne","2 à 1050g",null],["fischplaetzchen","tort man pla",null],["geschnetzeltes-zuercher-art","10 Pax",null],["gulaschsuppe","Der Kerntemperaturfühler soll während des Garens immer vollständig in der Flüssigkeit liegen.",null],["hausdressing","Mein Hausdressing. Genau so haben wir es im Restaurant serviert – und\nseitdem kaufe ich keines mehr. 🥗",null],["la-bomba","8 - 12 h Gärdauer Vorteig\n1 - 2 h Stockgare\n12 - 24 h Stückgare im Kühlschrank30 Minuten Aktivzeit\n50 - 60 Minuten Backzeit",null],["laksa","Laksa, die cremige südostasiatische Suppe aus Reisnudeln und einer Art Currypaste, bereiten wir hier mit Shrimps zu. Für eine vegetarische Laksa-Suppe kann man aber auch gut Tofu verwenden. So oder so – dieses spicy Nudelsuppe-Rezept schmeckt fantastisch!",null],["minestrone","100 g Parmesan gerieben\nEvt. Pesto",null],["multi-purpose-dough","½ cup (115g)whole milk \n½ cup (110g) water \n2 ½ tsp (11g) instant yeast \n3 ½ cups (525g) bread flour \n⅓ cup (70g) sugar \n1.5 tsp (9g) fine sea salt \n1 large egg\n1 large yolk\n⅓ cup (75g) unsalted butter softened, plus more for brushing\n¼ tsp (1g) malt powder\n3 g amylase\nEgg wash (1 egg + 1 tbsp water)",null],["pad-see-ew","– To make your noodles more manageable, it helps to place them in the microwave for 20 seconds or so to warm them up. Once you take them out, gently separate the noodles into lovely long strands – this extra step will ensure you don’t end with broken clumps in your pan",null],["san-francisco-sauerteigbrot","8 - 12 Std. Gärdauer Vorteig\n3 - 4 Std. Stockgare\n60 Min. Stückgare30 Min. Aktivzeit\n40 - 50 Min. Aktivzeit",null],["som-tam-2","Dazu passen Riesencrevetten vom Grill. Als Variante kann der Salat auch mit grünen Mangos zubereitet werden",null],["super-umami-ramen-broth-in-less-than-20-minutes","How do you turn only a few cheap vegetables into an umami-packed ramen broth in less than 20 minutes? Turns out you need two things—a pressure cooker and a high pH level. This flavor-packed broth is transformed with the addition of a household ingredient you might have never thought to use outside of baking—baking soda. The addition of baking soda increases Maillard reactions, darkening the broth and bumping up umami, all because the pH is raised ever so slightly. Add a pressure cooker to that and you’ll have yourself an amazing ramen broth in less than 20 minutes flat. What else do you need to know? It is a perfect base to build from as well. Want miso ramen? Add some miso. Want a silky tonkotsu? Add pork bones. No matter how you like it, it’s ready fast and full of flavor.",null],["swee-chilli-sauce-2","Sweet Chili Sauce\n🌶️🌶️🌶️\nEine Sauce wie KEINE andere!!\n🌶️ \nVergesst das künstliche sweet Chili und Sriracha-Zeugs in der Plastikflasche und macht sie selber!\n🌶️\nPeter Gordon, das Genie hinter diesem Rezept, ist der Prototyp des Fusion Cuisine Kochs. Geboren und aufgewachsen in Neuseeland, reiste er nach seiner Kochausbildung jahrelang durch die Länder Südostasiens und schaute in alle Töpfe, denen er nahekam. In den 1990ern eröffnete er in London den «Sugar Club». Das Restaurant wurde rasch zum Mekka von Asian-Food-Liebhabern, die den mediterranen Einfluss genauso schätzten. In dieser Zeit ass ich Jakobsmuscheln mit dieser Sauce im «Sugar Club» und erhielt von Peter Gordon auch das Rezept. Die selbstgemachte Sweet Chili Sauce, sie ist die Quintessenz der asiatischen Küche.Mehr Chilsaucen-Rezepte auf homemade.ch#sweetchili #petergordon #food #sweetchilisauce #chickenwings",null],["tort-man-pla-fischplaetzchen","Dazu passt Gurkenrelish.",null]]'::jsonb) x(v) where r.slug = x.v->>0;
